let state = DEFAULT_STATE();

function deepClone(obj) {
  return JSON.parse(JSON.stringify(obj));
}

function normalizeHexColor(value, fallback = '#ffffff') {
  if (!value) return fallback;
  const raw = String(value).trim();
  if (/^#[0-9a-fA-F]{6}$/.test(raw)) return raw.toLowerCase();
  if (/^[0-9a-fA-F]{6}$/.test(raw)) return ('#' + raw).toLowerCase();
  return fallback;
}

function advColor(adv, fallback = '#ffffff') {
  return normalizeHexColor(adv?.color, fallback);
}

function ensureGlobalTypography(seedScheme = null) {
  const seed = seedScheme || (state.styleSchemes || []).find(s => s?.isDefault) || (state.styleSchemes || [])[0] || {};
  const base = {
    font1:        seed.bodyFont  || 'Montserrat-Medium',
    font2:        seed.titleFont || 'Montserrat-ExtraBold',
    boldFont:     'Montserrat-Black',
    colorNeutral: advColor(seed.bodyFontAdv,  '#ffffff'),
    colorAccent:  advColor(seed.titleFontAdv, '#ffffff'),
    ...Object.fromEntries(SIZE_FIELDS.map(k => [k, Number(seed[k]) || DEFAULT_GLOBAL_SIZES[k]])),
  };
  state.globalTypography = {
    ...DEFAULT_GLOBAL_TYPOGRAPHY(),
    ...base,
    ...(state.globalTypography || {}),
  };
  state.globalTypography.colorNeutral = normalizeHexColor(state.globalTypography.colorNeutral);
  state.globalTypography.colorAccent  = normalizeHexColor(state.globalTypography.colorAccent);
  for (const key of SIZE_FIELDS) state.globalTypography[key] = Number(state.globalTypography[key]) || DEFAULT_GLOBAL_SIZES[key];
  return state.globalTypography;
}

function ensureSchemeTypography(scheme, global = ensureGlobalTypography()) {
  if (!scheme) return {};
  const existing = scheme.typography || {};
  // Migrate old key names from before v4.3.31
  if (existing.regularFont   !== undefined) { existing.font1        = existing.font1        ?? existing.regularFont;    delete existing.regularFont; }
  if (existing.highlightFont !== undefined) { existing.font2        = existing.font2        ?? existing.highlightFont;  delete existing.highlightFont; }
  if (existing.regularColor  !== undefined) { existing.colorNeutral = existing.colorNeutral ?? existing.regularColor;   delete existing.regularColor; }
  if (existing.highlightColor!== undefined) { existing.colorAccent  = existing.colorAccent  ?? existing.highlightColor; delete existing.highlightColor; }
  const typography = {};
  for (const key of TYPOGRAPHY_KEYS) {
    if (Object.prototype.hasOwnProperty.call(existing, key)) {
      typography[key] = SIZE_FIELD_SET.has(key)
        ? (existing[key] == null ? null : Number(existing[key]) || null)
        : (existing[key] || null);
    } else {
      // Legacy seed: first-time migration from old per-field scheme values
      let raw;
      if      (key === 'font1')        raw = scheme.bodyFont  || '';
      else if (key === 'font2')        raw = scheme.titleFont || '';
      else if (key === 'boldFont')     raw = '';
      else if (key === 'colorNeutral') raw = advColor(scheme.bodyFontAdv,  '');
      else if (key === 'colorAccent')  raw = advColor(scheme.titleFontAdv, '');
      else if (SIZE_FIELD_SET.has(key)) raw = scheme[key];
      else raw = '';
      const inherited = SIZE_FIELD_SET.has(key)
        ? Number(raw) === Number(global[key])
        : COLOR_TYPO_KEYS.has(key)
          ? normalizeHexColor(raw, global[key]) === normalizeHexColor(global[key])
          : raw === global[key];
      typography[key] = inherited ? null : (SIZE_FIELD_SET.has(key) ? Number(raw) || null : raw || null);
    }
  }
  scheme.typography = typography;
  return typography;
}

function resolveSchemeTypography(scheme, global = ensureGlobalTypography()) {
  const overrides = ensureSchemeTypography(scheme, global);
  return {
    font1:        overrides.font1        || global.font1,
    font2:        overrides.font2        || global.font2,
    boldFont:     overrides.boldFont     || global.boldFont,
    colorNeutral: normalizeHexColor(overrides.colorNeutral || global.colorNeutral),
    colorAccent:  normalizeHexColor(overrides.colorAccent  || global.colorAccent),
    ...Object.fromEntries(SIZE_FIELDS.map(k => [k, Number(overrides[k] ?? global[k]) || DEFAULT_GLOBAL_SIZES[k]])),
  };
}

// Advanced styling resolves Global → style one field at a time: a style's own
// value wins, null means "use Global's" (live). Colour is the exception — it
// comes from the Style tab's palette slots unless the element sets its own.
function resolveAdv(raw, glb) {
  const out = { ...FONT_ADV_DEFAULTS(), ...(glb || {}), color: '' };
  // A blank alignment/overflow in a style (or a retired value) follows Global.
  for (const [f, v] of Object.entries(raw || {})) if (v != null && !_advBlank(f, v)) out[f] = v;
  return out;
}
// A fresh advanced-styling object that follows Global for every field.
const INHERIT_ADV = () => Object.fromEntries(Object.keys(FONT_ADV_DEFAULTS()).map(k => [k, null]));

function setAdvColor(style, key, color) {
  style[key] = { ...FONT_ADV_DEFAULTS(), ...(style[key] || {}), color: normalizeHexColor(color) };
}

function applyTypographyToStyle(scheme, global = ensureGlobalTypography()) {
  const style = deepClone(scheme || DEFAULT_STYLE_SCHEME());
  const t = resolveSchemeTypography(style, global);
  // fontFields stores per-field overrides; palette is the fallback
  const ff = style.fontFields || {};
  for (const key of REGULAR_FONT_FIELDS)   style[key] = ff[key] || t.font1;
  for (const key of HIGHLIGHT_FONT_FIELDS)  style[key] = ff[key] || t.font2;
  for (const key of BOLD_FONT_FIELDS)       style[key] = ff[key] || t.boldFont;
  for (const key of SIZE_FIELDS)            style[key] = t[key];
  // Advanced styling: Global → style per field (resolveAdv). Colour: the
  // element's own colour if set, else the palette slot it belongs to.
  const gAdv = ensureGlobalFontAdv();
  for (const key of ADV_SCHEME_KEYS) {
    if (D2_ADV_INHERIT[key] && scheme[key] == null) continue; // follows Display 1, below
    style[key] = resolveAdv(scheme[key], gAdv[key]);
    if (!scheme[key]?.color) {
      style[key].color = normalizeHexColor(HIGHLIGHT_ADV_FIELDS.includes(key) ? t.colorAccent : t.colorNeutral);
    }
  }
  // Display 2 (LED-wall prop) advanced styling inherits Display 1 when the
  // scheme leaves it null. The loops above already resolved the Display 1
  // counterparts, so clone those over — live, so changing Display 1 carries to
  // Display 2 until the user overrides it. A concrete value is left untouched.
  for (const [d2, d1] of Object.entries(D2_ADV_INHERIT)) {
    if (scheme[d2] == null) style[d2] = deepClone(style[d1]);
  }
  return style;
}

// LED-wall advanced-styling field → the Display 1 field it inherits from when
// left null. Covers the Display 2 prop rows and the Response Card text rows,
// which all default to following their main-screen counterpart.
const D2_ADV_INHERIT = {
  propBodyFontAdv:  'bodyFontAdv',
  propPointFontAdv: 'pointFontAdv',
  propTitleFontAdv: 'titleFontAdv',
  propBoldFontAdv:  'boldFontAdv',
  rcBodyFontAdv:    'bodyFontAdv',
  rcTitleFontAdv:   'titleFontAdv',
};

// Materialize a scheme's advanced-styling object before an edit. A Display 2
// field that's inheriting (null) forks from its resolved Display 1 counterpart
// so the edit starts from what was on screen — not blank defaults, which would
// silently drop the inherited colour/style. Everything else forks from blanks.
function forkAdv(scheme, key) {
  if (scheme[key]) return scheme[key];
  const d1 = D2_ADV_INHERIT[key];
  scheme[key] = d1
    ? deepClone(styleForExport(scheme)[d1] || FONT_ADV_DEFAULTS())
    : INHERIT_ADV();
  return scheme[key];
}

function styleForExport(scheme) {
  const resolved = applyTypographyToStyle(scheme || activeStyleScheme());
  const glb = ensureGlobalLayout();
  for (const f of LAYOUT_FIELDS) {
    if (resolved[f] == null && glb[f] != null) resolved[f] = glb[f];
  }
  const glbMotion = ensureGlobalMotion();
  for (const f of MOTION_SCALAR_FIELDS) {
    if (resolved[f] == null && glbMotion[f] != null) resolved[f] = glbMotion[f];
  }
  if (resolved.buildOrders == null) resolved.buildOrders = glbMotion.buildOrders;
  if (resolved.rcElements == null) resolved.rcElements = ensureGlobalRcElements();
  const {
    id: _sid,
    name: _sname,
    isLocked: _sl,
    typography: _typo,
    fontFields: _ff,
    ...style
  } = resolved;
  return style;
}

function dn(key) {
  const n = (state.config.displayNames || {})[key];
  if (n) return n;
  if (key === 'mainScreen') return 'Main Screen';
  if (key === 'ledWall')    return 'LED Wall';
  if (key === 'monitor')    return 'Confidence Monitor';
  return key;
}

// ─── Pro7 runtime state (not persisted) ──────────────────────────────────────
const pro7rt = { connected: false, version: null, liveMacros: null, liveStageLayouts: null, liveStageScreens: null };
let   _fontList      = null;  // cached system font list (PostScript names)
let   _fontFamilyMap = null;  // family → [{ style, postscript }]

// ─── Persistence ──────────────────────────────────────────────────────────────

const STORAGE_KEY    = 'deckpro_state';
const GEN_HISTORY_KEY = 'deckpro_gen_history';
const GEN_HISTORY_MAX = 30;

let _savedTimer   = null;
let _autosaveTimer = null;
let _autosaveDue = false;   // an edit is waiting for autosaveDeck() to write it
const _undoStack = [];
const _redoStack = [];
const UNDO_LIMIT = 60;
let _skipUndoPush = false;

// saveState() runs AFTER each change, so the stack can't just record "state
// now" — that made the first Undo restore the state you were already in.
// Instead _undoBase holds the state as of the previous save, and a change
// pushes THAT. Selecting a different slide (activeId only) isn't an edit and
// pushes nothing; a burst of edits on the same item within a second (typing)
// folds into one step.
let _undoBase = null, _undoBaseKey = null, _undoAt = 0, _undoAtId = null;
const _undoContentKey = () => JSON.stringify(state, function (k, v) { return this === state && k === 'activeId' ? undefined : v; });
function resetUndoBase() {
  _undoBase = JSON.stringify(state);
  _undoBaseKey = _undoContentKey();
  _undoAt = 0;
}
function pushUndo() {
  if (_skipUndoPush) return;
  const key = _undoContentKey();
  if (_undoBase == null) { resetUndoBase(); return; }
  if (key === _undoBaseKey) { _undoBase = JSON.stringify(state); return; } // navigation only
  const now = Date.now();
  const sameBurst = now - _undoAt < 1000 && _undoAtId === state.activeId && _undoStack.length;
  if (!sameBurst) {
    _undoStack.push(_undoBase);
    if (_undoStack.length > UNDO_LIMIT) _undoStack.shift();
  }
  _undoAt = now; _undoAtId = state.activeId;
  _undoBase = JSON.stringify(state); _undoBaseKey = key;
  _redoStack.length = 0;
  updateUndoButtons();
}

function updateUndoButtons() {
  const u = document.getElementById('btn-undo');
  const r = document.getElementById('btn-redo');
  if (u) u.disabled = _undoStack.length === 0;
  if (r) r.disabled = _redoStack.length === 0;
}

// Edit menu ⌘Z / ⇧⌘Z: native text undo while typing in a field, deck-level
// undo everywhere else. (The menu accelerator used to always run the deck
// undo, yanking state out from under whatever field you were typing in.)
function editMenuUndo(redo) {
  const el = document.activeElement;
  const typing = el && (el.isContentEditable || el.tagName === 'TEXTAREA' ||
    (el.tagName === 'INPUT' && !/^(checkbox|radio|button|color|range|file)$/i.test(el.type)));
  if (typing) { document.execCommand(redo ? 'redo' : 'undo'); return; }
  if (redo) applyRedo(); else applyUndo();
}

function applyUndo() {
  if (!_undoStack.length) return;
  _redoStack.push(JSON.stringify(state));
  state = JSON.parse(_undoStack.pop());
  resetUndoBase();
  _skipUndoPush = true;
  saveState(); render(); syncHeaderInputs();
  _syncNotesPanelToDeck?.();  // keep notes panel in sync if undo crossed a load/clear
  _skipUndoPush = false;
  updateUndoButtons();
}

function applyRedo() {
  if (!_redoStack.length) return;
  _undoStack.push(JSON.stringify(state));
  state = JSON.parse(_redoStack.pop());
  resetUndoBase();
  _skipUndoPush = true;
  saveState(); render(); syncHeaderInputs();
  _syncNotesPanelToDeck?.();  // keep notes panel in sync if redo crossed a load/clear
  _skipUndoPush = false;
  updateUndoButtons();
}

let _saveFailed = false;
let _stateFileSaveFailed = false;
let _stateFileSaveTimer = null;

async function persistStateToFile() {
  try {
    const res = await fetch('/api/state', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ state }),
    });
    if (!res.ok) throw new Error('State save failed');
    _stateFileSaveFailed = false;
  } catch (e) {
    if (!_stateFileSaveFailed) {
      _stateFileSaveFailed = true;
      toast('error', 'Settings are not saving', 'DeckPro could not write its app-data state file. Your changes may not survive relaunch.');
    }
  }
}

function scheduleStateFileSave() {
  clearTimeout(_stateFileSaveTimer);
  _stateFileSaveTimer = setTimeout(persistStateToFile, 250);
}

function saveStateBeforeUnload() {
  const body = JSON.stringify({ state });
  try {
    if (navigator.sendBeacon) {
      navigator.sendBeacon('/api/state', new Blob([body], { type: 'application/json' }));
      return;
    }
  } catch (_) {}
  try {
    fetch('/api/state', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body,
      keepalive: true,
    });
  } catch (_) {}
}

function saveState() {
  pushUndo();
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
    _saveFailed = false;
  } catch (e) {
    // Don't fail silently — a save failure means the user's work isn't persisted.
    if (!_saveFailed) {
      _saveFailed = true;
      toast('error', 'Not saving locally', 'Local storage is full or blocked, so changes are not being saved. Export now to keep your work.');
    }
  }
  scheduleStateFileSave();
  const el = document.getElementById('saved-indicator');
  if (el) {
    el.classList.add('show');
    clearTimeout(_savedTimer);
    _savedTimer = setTimeout(() => el.classList.remove('show'), 1200);
  }
  clearTimeout(_autosaveTimer);
  _autosaveDue = true;
  _autosaveTimer = setTimeout(autosaveDeck, 1500);
  bumpSyncMeta();
}

function applySavedState(saved) {
  if (!saved || typeof saved !== 'object') return false;
  _undoBase = null; // re-baselined on the first save after loading
  try {
    state = Object.assign(DEFAULT_STATE(), saved);
    // Merge config separately so new keys get defaults
    const defaultCfg = DEFAULT_STATE().config;
    state.config = Object.assign(defaultCfg, saved.config || {});
    // Ensure nested responses object gets defaults
    state.config.responses = Object.assign(defaultCfg.responses, (saved.config || {}).responses || {});
    // Migration (pre-v4.29.0 → v4.29.0): decision + r1/r2/r3 -> r1/r2/r3/r4
    // (old decision becomes the new r1; old r1/r2/r3 shift down one). Detected
    // by the presence of the old decisionText key, so this only ever runs once.
    if (Object.prototype.hasOwnProperty.call(state.config.responses, 'decisionText')) {
      const old = state.config.responses;
      const DEFAULT_RC_NOTES_V1 = '{decision}\n1 — {r1}\n2 — {r2}\n3 — {r3}';
      const DEFAULT_RC_NOTES_V2 = '1 — {r1}\n2 — {r2}\n3 — {r3}\n4 — {r4}';
      const tmpl = old.notesTemplate;
      const migratedTmpl = (tmpl == null || tmpl === DEFAULT_RC_NOTES_V1)
        ? DEFAULT_RC_NOTES_V2
        : tmpl.replace(/\{(decision|r1|r2|r3)\}/g, (_, tag) => ({ decision: '{r1}', r1: '{r2}', r2: '{r3}', r3: '{r4}' }[tag]));
      state.config.responses = {
        r1: old.decisionText || '', r2: old.r1 || '', r3: old.r2 || '', r4: old.r3 || '',
        notesTemplate: migratedTmpl,
      };
      delete state.config.rcDecisionTextLocked;
    }
    // Feature flags
    state.config.features = Object.assign(DEFAULT_FEATURES(), (saved.config || {}).features || {});
    // Stage screen config
    state.config.stageScreen = Object.assign(DEFAULT_STAGESCREEN(), (saved.config || {}).stageScreen || {});
    // Restore style schemes — support old 'stylePresets' key for migration
    const savedSchemes = saved.styleSchemes || saved.stylePresets;
    if (Array.isArray(savedSchemes) && savedSchemes.length) {
      const LEGACY_PT_SIZE_FIELDS = ['bodySize', 'pointSize', 'titleSize', 'rcBodySize', 'rcTitleSize', 'startEndSize', 'propBodySize', 'propPointSize', 'propTitleSize'];
      state.styleSchemes = savedSchemes.map(p => {
        const DEF = DEFAULT_STYLE_SCHEME();
        // Migrate old half-point values to pt
        let out = deepClone(p);
        if (!p._ptSizes) {
          out = { ...out, _ptSizes: true };
          for (const f of LEGACY_PT_SIZE_FIELDS) if (out[f]) out[f] = Math.round(out[f] / 2);
        }
        // Merge with defaults so all new fields get values
        const merged = { ...DEF, ...out };
        // Clean up junk 'undefined' key left by a pre-4.7.2 double-bound color handler
        delete merged['undefined'];
        merged._needsTypographyMigration = !out.typography;
        // Merge nested fontAdv objects too
        for (const k of ['bodyFontAdv','propBodyFontAdv','boldFontAdv','propBoldFontAdv','notesBoldFontAdv','titleFontAdv','propTitleFontAdv','startEndFontAdv','notesFontAdv','liveFontAdv','queueFontAdv','pointFontAdv','propPointFontAdv','pointStackedFontAdv','rcBodyFontAdv','rcTitleFontAdv']) {
          // An explicit null on a Display 2 row means "follow Display 1" — keep it.
          merged[k] = (out[k] === null && D2_ADV_INHERIT[k]) ? null : { ...FONT_ADV_DEFAULTS(), ...(out[k] || {}) };
        }
        // Seed slide-notes font fields for schemes saved before notes were customizable
        if (!out.notesFont)     merged.notesFont     = DEF.notesFont;
        if (!out.notesSize)     merged.notesSize     = DEF.notesSize;
        // Seed point sizes added in v3.40.0
        if (!out.pointSize)     merged.pointSize     = merged.bodySize;
        if (!out.propPointSize) merged.propPointSize = merged.propBodySize;
        // Seed point layout split from body layout
        if (out.pointX === undefined) merged.pointX = merged.bodyX;
        if (out.pointY === undefined) merged.pointY = merged.bodyY;
        if (out.pointW === undefined) merged.pointW = merged.bodyW;
        if (out.pointH === undefined) merged.pointH = merged.bodyH;
        if (out.propPointX === undefined) merged.propPointX = merged.propBodyX;
        if (out.propPointY === undefined) merged.propPointY = merged.propBodyY;
        if (out.propPointW === undefined) merged.propPointW = merged.propBodyW;
        if (out.propPointH === undefined) merged.propPointH = merged.propBodyH;
        if (!out.rcBodySize)  merged.rcBodySize  = merged.bodySize;
        if (!out.rcTitleSize) merged.rcTitleSize = merged.titleSize;
        if (!out.rcBodyFont)  merged.rcBodyFont  = merged.bodyFont;
        if (!out.rcTitleFont) merged.rcTitleFont = merged.titleFont;
        if (out.rcBodyX === undefined) merged.rcBodyX = merged.bodyX;
        if (out.rcBodyY === undefined) merged.rcBodyY = merged.bodyY;
        if (out.rcBodyW === undefined) merged.rcBodyW = merged.bodyW;
        if (out.rcBodyH === undefined) merged.rcBodyH = merged.bodyH;
        if (out.rcTitleX === undefined) merged.rcTitleX = merged.titleX;
        if (out.rcTitleY === undefined) merged.rcTitleY = merged.titleY;
        if (out.rcTitleW === undefined) merged.rcTitleW = merged.titleW;
        if (out.rcTitleH === undefined) merged.rcTitleH = merged.titleH;
        if (out.rcAutoTitleY === undefined) merged.rcAutoTitleY = merged.autoTitleY;
        if (out.rcTitleAutoGap === undefined) merged.rcTitleAutoGap = merged.titleAutoGap;
        // Seed prop title font split added in v3.40.0
        if (!out.propTitleFont)    merged.propTitleFont    = merged.titleFont;
        if (out.propTitleFontAdv === undefined) merged.propTitleFontAdv = JSON.parse(JSON.stringify(merged.titleFontAdv));
        else if (out.propTitleFontAdv === null) merged.propTitleFontAdv = null;
        else                       merged.propTitleFontAdv = { ...FONT_ADV_DEFAULTS(), ...out.propTitleFontAdv };
        // boldFont / propBoldFont were removed (emphasis renders as plain \b on the
        // body font). Carry the bold *advanced* styling forward as an internal
        // fallback for point styling on schemes saved before the point-font split.
        if (out.propBoldFontAdv === undefined) merged.propBoldFontAdv = JSON.parse(JSON.stringify(merged.boldFontAdv));
        else if (out.propBoldFontAdv === null) merged.propBoldFontAdv = null;
        else                      merged.propBoldFontAdv = { ...FONT_ADV_DEFAULTS(), ...out.propBoldFontAdv };
        // Seed the split point fonts from the old bold fonts for pre-split schemes
        // (preserves existing point-text styling — point used to share the bold font).
        if (!out.pointFont)         merged.pointFont         = out.boldFont || merged.pointFont;
        if (!out.pointFontAdv)      merged.pointFontAdv      = JSON.parse(JSON.stringify(merged.boldFontAdv));
        else                        merged.pointFontAdv      = { ...FONT_ADV_DEFAULTS(), ...out.pointFontAdv };
        if (!out.propPointFont)     merged.propPointFont     = out.propBoldFont || out.boldFont || merged.propPointFont;
        if (out.propPointFontAdv === undefined) merged.propPointFontAdv = JSON.parse(JSON.stringify(merged.propBoldFontAdv));
        else if (out.propPointFontAdv === null) merged.propPointFontAdv = null;
        else merged.propPointFontAdv = { ...FONT_ADV_DEFAULTS(), ...out.propPointFontAdv };
        if (out.rcBodyFontAdv === undefined) merged.rcBodyFontAdv = JSON.parse(JSON.stringify(merged.bodyFontAdv));
        else if (out.rcBodyFontAdv === null) merged.rcBodyFontAdv = null;
        else merged.rcBodyFontAdv = { ...FONT_ADV_DEFAULTS(), ...out.rcBodyFontAdv };
        if (out.rcTitleFontAdv === undefined) merged.rcTitleFontAdv = JSON.parse(JSON.stringify(merged.titleFontAdv));
        else if (out.rcTitleFontAdv === null) merged.rcTitleFontAdv = null;
        else merged.rcTitleFontAdv = { ...FONT_ADV_DEFAULTS(), ...out.rcTitleFontAdv };
        // Drop the removed orphan fields if an old scheme carried them.
        delete merged.titleText; delete merged.titleShadow;
        delete merged.boldFont;  delete merged.propBoldFont;
        // Strip legacy isDefault flag — all schemes are equal now
        delete merged.isDefault;
        if (p.isLocked === undefined) merged.isLocked = false;
        // Merge buildOrders — fill any missing tab keys with defaults. A scheme
        // that explicitly has buildOrders: null (inheriting Global) stays null —
        // only materialize/fill defaults for schemes that HAVE their own object.
        if (out.buildOrders === null) {
          merged.buildOrders = null;
        } else {
          merged.buildOrders = deepClone({ ...DEF.buildOrders, ...(out.buildOrders || {}) });
          // Migrate old 'this slide' → 'body', and drop the retired 'atem_gradient'
          // build-order entries (the gradient is now a Pro7 macro, not an element).
          for (const tabKey of Object.keys(merged.buildOrders)) {
            if (Array.isArray(merged.buildOrders[tabKey])) {
              merged.buildOrders[tabKey] = merged.buildOrders[tabKey]
                .filter(entry => entry.element !== 'atem_gradient')
                .map(entry => entry.element === 'this slide' ? { ...entry, element: 'body' } : entry);
            }
          }
        }
        // Migration (pre-v4.29.0 → v4.29.0): a scheme with its own forked
        // rcElements (not inheriting Global) needs the same role relabel as
        // globalRcElements — see migrateRcElementsV2.
        if (Array.isArray(merged.rcElements)) merged.rcElements = migrateRcElementsV2(merged.rcElements);
        return deepClone(merged);
      });
    }
    const seedGlobalScheme = state.styleSchemes.find(s => s.isDefault) || state.styleSchemes[0] || DEFAULT_STYLE_SCHEME();
    const _rawGT = saved.globalTypography ? { ...saved.globalTypography } : null;
    // Migrate old key names (pre-v4.3.31)
    if (_rawGT) {
      if (_rawGT.regularFont   !== undefined) { _rawGT.font1        = _rawGT.font1        ?? _rawGT.regularFont;    delete _rawGT.regularFont; }
      if (_rawGT.highlightFont !== undefined) { _rawGT.font2        = _rawGT.font2        ?? _rawGT.highlightFont;  delete _rawGT.highlightFont; }
      if (_rawGT.regularColor  !== undefined) { _rawGT.colorNeutral = _rawGT.colorNeutral ?? _rawGT.regularColor;   delete _rawGT.regularColor; }
      if (_rawGT.highlightColor!== undefined) { _rawGT.colorAccent  = _rawGT.colorAccent  ?? _rawGT.highlightColor; delete _rawGT.highlightColor; }
    }
    state.globalTypography = _rawGT
      ? { ...DEFAULT_GLOBAL_TYPOGRAPHY(), ..._rawGT }
      : {
          font1:        seedGlobalScheme.bodyFont  || 'Montserrat-Medium',
          font2:        seedGlobalScheme.titleFont || 'Montserrat-ExtraBold',
          boldFont:     'Montserrat-Black',
          colorNeutral: advColor(seedGlobalScheme.bodyFontAdv,  '#ffffff'),
          colorAccent:  advColor(seedGlobalScheme.titleFontAdv, '#ffffff'),
          ...Object.fromEntries(SIZE_FIELDS.map(k => [k, Number(seedGlobalScheme[k]) || DEFAULT_GLOBAL_SIZES[k]])),
        };
    state.globalTypography.colorNeutral = normalizeHexColor(state.globalTypography.colorNeutral);
    state.globalTypography.colorAccent  = normalizeHexColor(state.globalTypography.colorAccent);
    for (const key of SIZE_FIELDS) state.globalTypography[key] = Number(state.globalTypography[key]) || DEFAULT_GLOBAL_SIZES[key];
    for (const scheme of state.styleSchemes) {
      if (scheme._needsTypographyMigration) delete scheme.typography;
      ensureSchemeTypography(scheme, state.globalTypography);
      delete scheme._needsTypographyMigration;
    }
    state.globalLayout = saved.globalLayout
      ? { ...DEFAULT_GLOBAL_LAYOUT(), ...saved.globalLayout }
      : DEFAULT_GLOBAL_LAYOUT();
    if (saved.globalFontAdv) {
      state.globalFontAdv = DEFAULT_GLOBAL_FONT_ADV();
      for (const k of ADV_SCHEME_KEYS) {
        state.globalFontAdv[k] = { ...FONT_ADV_DEFAULTS(), ...(saved.globalFontAdv[k] || {}) };
      }
    } else {
      state.globalFontAdv = DEFAULT_GLOBAL_FONT_ADV();
    }
    state.globalMotion = saved.globalMotion
      ? { ...DEFAULT_GLOBAL_MOTION(), ...saved.globalMotion, buildOrders: saved.globalMotion.buildOrders || DEFAULT_GLOBAL_MOTION().buildOrders }
      : DEFAULT_GLOBAL_MOTION();
    state.globalMacros        = Array.isArray(saved.globalMacros)        ? saved.globalMacros        : [];
    state.globalStageDisplays = Array.isArray(saved.globalStageDisplays) ? saved.globalStageDisplays : [];
    state.globalRcElements    = migrateRcElementsV2(Array.isArray(saved.globalRcElements) ? saved.globalRcElements : DEFAULT_RC_ELEMENTS());
    // Support old 'activeStyleId' key for migration
    state.activeSchemeId = saved.activeSchemeId || saved.activeStyleId
      || (state.styleSchemes[0]?.id ?? 'default');
    state.showBlanks = saved.showBlanks ?? true;
    // Migrate global customMacros → per-scheme macros (v4.0.10+)
    if (Array.isArray(saved.config?.customMacros) && saved.config.customMacros.length) {
      const defaultScheme = state.styleSchemes.find(s => s.isDefault) || state.styleSchemes[0];
      if (defaultScheme && !defaultScheme.macros?.length) {
        defaultScheme.macros = saved.config.customMacros;
      }
    }

    // Migrate global stageScreen → per-scheme stageDisplays + stageScreenConfig (v4.2.2+)
    const _ss = saved.config?.stageScreen;
    if (_ss) {
      for (const scheme of state.styleSchemes) {
        if (!scheme.stageDisplays?.length) {
          scheme.stageDisplays = [
            { id: uid(), name: _ss.rcLayoutName      || '', uuid: _ss.rcLayoutUuid      || '', triggers: ['rcBlank', 'rcContent'] },
            { id: uid(), name: _ss.messageLayoutName || '', uuid: _ss.messageLayoutUuid || '', triggers: ['scripture', 'point', 'blank', 'image', 'custom'] },
          ].filter(d => d.name || d.uuid);
        }
      }
    }

    // Migrate legacy 'rc' macro trigger → 'rcContent' (v4.2.4+)
    for (const scheme of state.styleSchemes) {
      for (const macro of (scheme.macros || [])) {
        if (Array.isArray(macro.triggers) && macro.triggers.includes('rc')) {
          macro.triggers = macro.triggers.map(t => t === 'rc' ? 'rcContent' : t);
        }
      }
    }

    // Migrate role-based stageDisplays → trigger-based (v4.3.0+)
    for (const scheme of state.styleSchemes) {
      if (!scheme.stageDisplays?.length) continue;
      let screenEntry = null;
      scheme.stageDisplays = scheme.stageDisplays.map(d => {
        if (!d.role) return d; // already trigger-based
        if (d.role === 'screen') { screenEntry = d; return null; }
        const triggers = d.role === 'msgLayout'
          ? ['scripture', 'point', 'blank', 'image', 'custom']
          : d.role === 'rcLayout'
          ? ['rcBlank', 'rcContent']
          : (d.triggers || []);
        return { id: d.id, name: d.name || '', uuid: d.uuid || '', triggers };
      }).filter(Boolean);
    }

    // Fold 'rcHold' into 'rcContent' (v4.32.0+): the Response Card package is
    // now just RC Blank + one Response Card slide, which replaced both the
    // old content slides and the old Hold slide — so the two triggers mean the
    // same cue. builder.js still honors 'rcHold' too, as a safety net.
    const _foldRcHold = list => {
      for (const item of (list || [])) {
        if (Array.isArray(item.triggers) && item.triggers.includes('rcHold')) {
          item.triggers = [...new Set(item.triggers.map(t => t === 'rcHold' ? 'rcContent' : t))];
        }
      }
    };
    for (const scheme of state.styleSchemes) { _foldRcHold(scheme.macros); _foldRcHold(scheme.stageDisplays); }
    _foldRcHold(state.globalMacros);
    _foldRcHold(state.globalStageDisplays);

    // Migrate old string[] bullets → spans[][] for revealing points
    for (const sl of (state.slides || [])) {
      if (sl.type === 'point' && sl.mode === 'revealing' && Array.isArray(sl.bullets)) {
        sl.bullets = sl.bullets.map(b =>
          (typeof b === 'string') ? [{ text: b, bold: false }] : b
        );
      }
    }

    // Migrate pre-v3.24.0 bold:true spans to alt:true.
    // Before v3.24.0, bold meant the scheme emphasis font (Montserrat-Black).
    // Now bold = plain \b; alt = emphasis font. Any span with bold but no alt key is old-style.
    function migrateBoldToAlt(spans) {
      if (!Array.isArray(spans)) return spans;
      return spans.map(s => (s.bold && s.alt === undefined) ? { ...s, bold: false, alt: true } : s);
    }
    for (const sl of (state.slides || [])) {
      if (sl.bodies) sl.bodies = sl.bodies.map(b => migrateBoldToAlt(b));
      if (sl.body)   sl.body   = migrateBoldToAlt(sl.body);
      if (sl.spans)  sl.spans  = migrateBoldToAlt(sl.spans);
      if (sl.blankSpans) sl.blankSpans = migrateBoldToAlt(sl.blankSpans);
      if (sl.type === 'point' && sl.mode === 'revealing' && Array.isArray(sl.bullets)) {
        sl.bullets = sl.bullets.map(b => Array.isArray(b) ? migrateBoldToAlt(b) : b);
      }
    }

    if (!state.slides.find(s => s.type === 'start'))
      state.slides.unshift({ id: 'start', type: 'start', label: 'Start of Notes', fixed: true });
    if (!state.slides.find(s => s.type === 'end'))
      state.slides.push({ id: 'end', type: 'end', label: 'End of Notes', fixed: true });
    // Migrate the old default start label "START" → "Start of Notes" (match End of Notes)
    const startSlide = state.slides.find(s => s.type === 'start');
    if (startSlide && (startSlide.label === 'START' || !startSlide.label)) {
      startSlide.label = 'Start of Notes';
      if (startSlide.text === 'START') startSlide.text = 'Start of Notes';
    }
    return true;
  } catch (e) {
    setTimeout(() => toast('error', 'Could not restore your last state',
      'The saved app data was unreadable, so DeckPro started fresh.'), 400);
    return false;
  }
}

async function loadState() {
  try {
    const res = await fetch('/api/state');
    const data = await res.json();
    if (data.ok && data.state && applySavedState(data.state)) return;
  } catch (_) {
    // Running from a plain static preview or an older build — fall back below.
  }

  let raw = null;
  try {
    raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return;
    if (applySavedState(JSON.parse(raw))) scheduleStateFileSave();
  } catch (e) {
    // Don't silently discard a deck we couldn't parse — preserve a backup and tell the user.
    if (raw) {
      try { localStorage.setItem(STORAGE_KEY + '_corrupt_backup', raw); } catch (_) {}
      setTimeout(() => toast('error', 'Could not restore your last deck',
        'The saved data was unreadable, so a fresh deck was started. A backup copy was kept in case it can be recovered.'), 400);
    }
  }
}

function syncHeaderInputs() {
  const s   = state.config.seriesName?.trim()  || '';
  const t   = state.config.messageTitle?.trim() || '';
  const raw = state.config.weekDate || '';
  const d   = raw ? new Date(raw + 'T00:00:00').toLocaleDateString('en-US', { month: 'short', day: 'numeric' }) : '';
  const isDraft = !state.currentDeckId;

  const meta  = document.getElementById('deck-header-meta');
  const elSeries = document.getElementById('dhm-series');
  const elTitle  = document.getElementById('dhm-title');
  const elDate   = document.getElementById('dhm-date');
  const sep1     = document.getElementById('dhm-sep1');
  const sep2     = document.getElementById('dhm-sep2');

  if (meta) meta.classList.toggle('dhm--draft', isDraft && !s && !t);

  if (elSeries) elSeries.textContent = isDraft && !s && !t ? 'Draft' : s;
  if (elTitle)  elTitle.textContent  = isDraft && !s && !t ? '' : t;
  if (elDate)   elDate.textContent   = isDraft && !s && !t ? '' : d;
  if (sep1) sep1.style.display = (s && t) ? '' : 'none';
  if (sep2) sep2.style.display = ((t && d) || (s && d && !t)) && !isDraft ? '' : 'none';

  const dl = document.getElementById('series-datalist');
  if (dl) {
    const recent = state.config.recentSeries || [];
    dl.innerHTML = recent.map(r => `<option value="${esc(r)}">`).join('');
  }
}

// ─── Helpers ──────────────────────────────────────────────────────────────────

function uid() {
  return (typeof crypto !== 'undefined' && crypto.randomUUID)
    ? crypto.randomUUID()
    : 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
        const r = Math.random() * 16 | 0;
        return (c === 'x' ? r : (r & 0x3 | 0x8)).toString(16);
      });
}
function syncUidCounter() { /* no-op — UUIDs never collide */ }

function esc(s) {
  return String(s ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

// ─── Confirm modal helper ─────────────────────────────────────

function showConfirmModal(title, body, confirmLabel, onConfirm) {
  document.getElementById('g-confirm-overlay')?.remove();
  const ov = document.createElement('div');
  ov.id = 'g-confirm-overlay';
  ov.className = 'g-confirm-overlay';
  ov.innerHTML = '<div class="g-confirm-modal">' +
    '<p class="g-confirm-title">' + esc(title) + '</p>' +
    '<p class="g-confirm-body">' + esc(body) + '</p>' +
    '<div class="g-confirm-btns">' +
    '<button class="btn g-confirm-cancel">Cancel</button>' +
    '<button class="btn g-confirm-ok">' + esc(confirmLabel) + '</button>' +
    '</div></div>';
  document.body.appendChild(ov);
  ov.querySelector('.g-confirm-cancel').addEventListener('click', () => ov.remove());
  ov.querySelector('.g-confirm-ok').addEventListener('click', () => { ov.remove(); onConfirm(); });
  ov.addEventListener('click', e => { if (e.target === ov) ov.remove(); });
}

// ─── Tooltip system ───────────────────────────────────────────

let _tipTarget = null;
let _tipTimeout = null;

// ─── Diagnostics ──────────────────────────────────────────────────────────────

// Rolling log of recent app activity (toasts + JS errors) — a "temp log" a
// user can hand over verbatim (via Export Diagnostic Bundle) to show exactly
// what led up to a problem, not just the app's general state at the time.
const _eventLog = [];
function logEvent(kind, msg, extra) {
  _eventLog.push({ at: new Date().toISOString(), kind, msg: String(msg || '').slice(0, 500), extra: extra ? String(extra).slice(0, 500) : undefined });
  if (_eventLog.length > 50) _eventLog.shift();
}
function initDiagnostics() {
  window.addEventListener('error', e => logEvent('error', e.message, e.filename ? `${e.filename}:${e.lineno}` : ''));
  window.addEventListener('unhandledrejection', e => logEvent('promise', e.reason && e.reason.message ? e.reason.message : e.reason));
  const origErr = console.error.bind(console);
  console.error = (...args) => { try { logEvent('console', args.map(a => (a && a.message) || a).join(' ')); } catch (_) {} origErr(...args); };
}

async function buildDiagnosticBundle() {
  const cfg = state.config || {};
  // Settings minus secrets.
  const { bibleApiKey, pro7Password, ...safeConfig } = cfg;
  const slides = state.slides || [];
  const typeCounts = slides.reduce((m, s) => { m[s.type] = (m[s.type] || 0) + 1; return m; }, {});
  const schemes = state.styleSchemes || [];
  const bundle = {
    app: 'DeckPro',
    version: APP_VERSION,
    generatedAt: new Date().toISOString(),
    platform: { userAgent: navigator.userAgent, platform: navigator.platform, language: navigator.language },
    secretsPresent: { bibleApiKey: !!bibleApiKey, pro7Password: !!pro7Password },
    config: safeConfig,
    deck: {
      slideCount: slides.length,
      typeCounts,
      activeId: state.activeId,
      showBlanks: state.showBlanks,
    },
    schemes: { count: schemes.length, activeSchemeId: state.activeSchemeId, names: schemes.map(s => s.name) },
    macros: (activeStyleScheme().macros || []).map(m => ({ name: m.name, hasUuid: !!m.uuid, triggers: m.triggers || [] })),
    pro7: { connected: !!(typeof pro7rt !== 'undefined' && pro7rt.connected), liveMacroCount: (typeof pro7rt !== 'undefined' && pro7rt.liveMacros ? pro7rt.liveMacros.length : 0), schemeMacros: (activeStyleScheme()?.macros || []).length },
    library: (typeof _libStatus !== 'undefined' && _libStatus) ? { libraryDir: _libStatus.libraryDir, deckCount: _libStatus.deckCount } : null,
    exportHistory: (typeof loadGenHistory === 'function' ? loadGenHistory() : []).slice(0, 10).map(h => ({ name: h.fileName || h.name, at: h.at || h.date, ok: h.ok !== false })),
    eventLog: _eventLog,
  };
  try {
    const res = await fetch('/api/setup/doctor');
    const data = await res.json();
    if (data.ok) bundle.machineSetup = data;
  } catch (_) {}
  return bundle;
}

async function exportDiagnosticBundle() {
  let json;
  try { json = JSON.stringify(await buildDiagnosticBundle(), null, 2); }
  catch (e) { toast('error', 'Could not build diagnostics', e.message); return; }
  try {
    const blob = new Blob([json], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const ts = new Date().toISOString().replace(/[:.]/g, '-').slice(0, 19);
    const a = Object.assign(document.createElement('a'), { href: url, download: `deckpro-diagnostic-${ts}.json` });
    document.body.appendChild(a); a.click();
    setTimeout(() => { URL.revokeObjectURL(url); a.remove(); }, 1000);
    toast('success', 'Diagnostic bundle saved', 'Secrets (API key, password) are excluded.');
  } catch (e) {
    toast('error', 'Could not save diagnostics', e.message);
  }
}

function initTooltip() {
  const tip = document.createElement('div');
  tip.id = 'g-tip';
  tip.className = 'g-tip';
  document.body.appendChild(tip);

  document.addEventListener('mouseover', e => {
    const el = e.target.closest('[data-tip],[data-tip-key]');
    if (!el || el === _tipTarget) return;
    _tipTarget = el;
    clearTimeout(_tipTimeout);
    _tipTimeout = setTimeout(() => {
      const key  = el.getAttribute('data-tip-key');
      let text = key ? (TOOLTIPS[key] || key) : el.getAttribute('data-tip');
      if (!text) return;
      text = text.replace(/\\n/g, '\n'); // accept a literal "\n" in the attribute as a line break
      // Optional title: text before the first newline (or an explicit data-tip-title)
      const title = el.getAttribute('data-tip-title')
        || (text.includes('\n') ? text.slice(0, text.indexOf('\n')) : '');
      const body  = title && !el.getAttribute('data-tip-title')
        ? text.slice(text.indexOf('\n') + 1)
        : text;
      tip.innerHTML = (title ? `<span class="g-tip-title">${esc(title)}</span>` : '') + esc(body);
      tip.classList.add('visible');
      const r = el.getBoundingClientRect();
      const tw = tip.offsetWidth;
      let left = r.left + r.width / 2 - tw / 2;
      left = Math.max(8, Math.min(left, window.innerWidth - tw - 8));
      tip.style.left = left + 'px';
      tip.style.top  = (r.top - tip.offsetHeight - 8) + 'px';
    }, 700);
  });

  document.addEventListener('mouseout', e => {
    const el = e.target.closest('[data-tip],[data-tip-key]');
    if (!el) return;
    _tipTarget = null;
    clearTimeout(_tipTimeout);
    tip.classList.remove('visible');
  });
}

// ─── Rich-text helpers ────────────────────────────────────────────────────────

function extractSpans(el) {
  const spans = [];
  function walk(node, fmt) {
    if (node.nodeType === 3) {
      if (node.textContent) spans.push({ text: node.textContent, ...fmt });
    } else if (node.nodeType === 1) {
      if (node.tagName === 'BR') { spans.push({ text: '\n', ...fmt }); return; }
      if (node.tagName === 'SUP' || (node.classList && node.classList.contains('vnum'))) {
        const t = node.textContent;
        if (t) spans.push({ text: t, verseNum: true, super: node.tagName === 'SUP', alt: false, bold: false, italic: false, underline: false });
        return;
      }
      if (node.tagName === 'SPAN' && node.classList.contains('digit-warn')) {
        for (const child of node.childNodes) walk(child, fmt);
        return;
      }
      const alt       = fmt.alt       || (node.tagName === 'SPAN' && node.classList.contains('alt-fmt'));
      const bold      = !alt && (fmt.bold      || node.tagName === 'B' || node.tagName === 'STRONG'
                        || node.style.fontWeight === 'bold' || node.style.fontWeight === '700');
      const italic    = fmt.italic    || node.tagName === 'I' || node.tagName === 'EM'
                        || node.style.fontStyle === 'italic';
      const underline = fmt.underline || node.tagName === 'U'
                        || node.style.textDecoration === 'underline'
                        || node.style.textDecorationLine === 'underline';
      for (const child of node.childNodes) walk(child, { alt, bold, italic, underline });
    }
  }
  walk(el, { alt: false, bold: false, italic: false, underline: false });
  return spans.reduce((acc, s) => {
    const last = acc[acc.length - 1];
    if (last && !last.verseNum && !s.verseNum && last.alt === s.alt && last.bold === s.bold && last.italic === s.italic && last.underline === s.underline)
      last.text += s.text;
    else
      acc.push({ text: s.text, alt: !!s.alt, bold: !!s.bold, italic: !!s.italic, underline: !!s.underline, ...(s.verseNum ? { verseNum: true, super: !!s.super } : {}) });
    return acc;
  }, []);
}

// Extract plain text from a bullet (string or spans array)
function bulletToText(bullet) {
  if (typeof bullet === 'string') return bullet;
  return (bullet || []).map(s => s.text || '').join('');
}

function spansToHtml(spans) {
  return (spans || []).map(s => {
    if (s.verseNum) {
      const inner = esc(s.text);
      return s.super ? `<sup class="vnum">${inner}</sup>` : `<span class="vnum">${inner}</span>`;
    }
    let html = esc(s.text);
    if (s.underline) html = `<u>${html}</u>`;
    if (s.italic)    html = `<em>${html}</em>`;
    if (s.bold)      html = `<strong>${html}</strong>`;
    return html;
  }).join('');
}

const DIGIT_PREFIX_RE = /^(\d+)(?:\s|["'\u201c\u201d\u2018\u2019])/;

// Like spansToHtml but converts \n spans → <br> for the preview canvas
function spansToHtmlPreview(spans) {
  return (spans || []).map((s, i) => {
    if (s.text === '\n') return '<br>';
    if (s.verseNum) {
      const inner = esc(s.text);
      return s.super ? `<sup class="vnum">${inner}</sup>` : `<span class="vnum">${inner}</span>`;
    }
    let html = esc(s.text).replace(/\n/g, '<br>');
    if (i === 0) {
      const dm = s.text.match(DIGIT_PREFIX_RE);
      if (dm) {
        const rest = esc(s.text.slice(dm[1].length)).replace(/\n/g, '<br>');
        html = `<span class="digit-warn">${esc(dm[1])}</span>${rest}`;
      }
    }
    if (s.underline) html = `<u>${html}</u>`;
    if (s.italic)    html = `<em>${html}</em>`;
    if (s.bold)      html = `<strong>${html}</strong>`;
    if (s.alt)       html = `<span class="alt-fmt">${html}</span>`;
    return html;
  }).join('');
}

function activeStyleScheme() {
  return (state.styleSchemes || []).find(s => s.id === state.activeSchemeId) || (state.styleSchemes || [])[0] || {};
}

// ─── Fit Width: weighted line-break scoring ──────────────────────────────────
//
// Instead of one rigid rule ("keep the same line count as full width"), Fit
// Width now proposes many candidate box widths, reads the line breakdown each
// one induces, and scores it against a set of tunable penalties. The lowest
// cost wins. Tune the feel by editing FIT_WEIGHTS — nothing else changes.
//
// Line count is a TIER, not a term here — see computeOptimalBodyWidth, which
// only ever scores candidates that share the floor line count N. Every term
// below is a soft, within-tier preference: the competing preferences are
// supposed to compete, they just can't add a line to win. An internal break
// costs 0..breakMidClause depending on the punctuation it follows; a lone
// word (or a bare function word) at the end of ANY line costs extra; an
// emphasis (bold) run split across a break costs `highlightSplit`; and
// `raggedPerPx` rewards even line widths, for every type — scripture used to
// have no evenness term at all, which is how a widow like "Great" could end
// a line at zero cost. Hard constraints (a line wider than the box, or more
// than maxLines) disqualify a candidate outright.
const FIT_WEIGHTS = {
  orphan:          60,   // last line is a single short word (widow)
  orphanMaxChars:   7,   // "short" = this many letters or fewer
  breakSentence:    0,   // breaking after . ! ? … is the ideal break point
  breakClauseMark:  3,   // after ; : ,
  breakDash:        6,   // after — – or -
  breakMidClause:  10,   // breaking with NO punctuation at all is the worst place
  lineEndFunction: 12,   // a line ends on a bare function word (the, of, and, ...)
  highlightSplit:  40,   // an emphasis (bold) run straddling two lines
  raggedPerPx:    0.04,  // penalty per px of line-width std-deviation — every type
  maxLines:         6,   // hard cap on line count
  pad:             24,   // minimum breathing room added to the winning width
  padPerPt:       0.5,   // ...or this much per point of font size, if larger
};
// Bump when Fit Width's output changes for the same inputs, so every cached
// result (see _fitHash) is treated as stale and re-measured at next export.
const FIT_REV = 2;

// Function words that read badly ending a line ("...your heart and",
// "...all things through") — ending a line on one of these with no
// punctuation of its own to justify the break earns lineEndFunction. This is
// the exact list from the spec, not a fuzzy "short word" heuristic: it's
// what actually reads as a mid-clause break in practice, and is far more
// reliable to detect than guessing from word length.
const FIT_FUNCTION_WORDS = new Set([
  'the','of','and','a','an','to','in','for','with','on','at','by','from','as',
]);

// Flatten spans into words. A word is a maximal run of non-whitespace and can
// cross span boundaries (emphasis can start mid-word), so each word keeps the
// formatted pieces it's made of in `segs` — that's what gets measured, and
// what _fitSpansFromWinningLayout writes back out, so a hard-broken layout
// keeps every span property (alt emphasis, bold, italic, underline, verse
// numbers) instead of only the three it used to know about.
// `emph` marks a word as part of an emphasis run (the alt font for scripture,
// bold for points — see _fitSegFmt), which the scorer avoids splitting.
// `mtext` on each segment carries the capitalization-transformed text used
// ONLY for rendering into the measurement DOM (see _fitCaseText) — `text`
// stays the real, original string. Keeping them separate matters: `text` is
// what ends up in slide._fitBrokenText → bodyDisplayText at export, and a
// cased `text` would fail the equality guard there and drop the hard breaks.
function _fitWordList(spans, baseCap = '', boldCap = '', type = 'body') {
  const words = [];
  let cur = null;
  const flush = () => { if (cur) { words.push(cur); cur = null; } };
  for (const s of (spans || [])) {
    if (!s || !s.text) continue;
    const fmt = _fitSegFmt(s, type);
    for (const piece of String(s.text).split(/(\s+)/)) {
      if (!piece) continue;
      if (/^\s+$/.test(piece)) { flush(); continue; }
      if (!cur) cur = { segs: [] };
      cur.segs.push({ text: piece, mtext: _fitCaseText(piece, fmt.emph ? boldCap : baseCap), fmt, src: s });
    }
  }
  flush();
  for (const w of words) {
    w.text = w.segs.map(g => g.text).join('');
    w.emph = w.segs.some(g => g.fmt.emph);
    // Three punctuation tiers, ranked best→worst: sentence-final beats a
    // clause mark (; : ,) beats a dash. No trailing punctuation at all
    // (rank 0) is worse than any of them — that's breakMidClause.
    const m = w.text.match(/[.!?…:;,—–-]+["'”’)\]]*$/);
    const end = m ? m[0].replace(/["'”’)\]]+$/, '') : '';
    w.punctRank = /[.!?…]$/.test(end) ? 3 : /[:;,]$/.test(end) ? 2 : /[—–-]$/.test(end) ? 1 : 0;
    const bare = w.text.replace(/[^A-Za-z']/g, '').toLowerCase();
    // A runt only if it carries no trailing punctuation of its own — a comma or
    // period after the word already makes it a legitimate place to break.
    w.runt = w.punctRank === 0 && FIT_FUNCTION_WORDS.has(bare);
  }
  return words;
}

// How one span renders, reduced to what changes its width. Scripture/body
// emphasis is `alt` (a switch to the bold row's font — rtf.buildSpanContent);
// `bold` there is a plain \b on whichever font is current. Points have no
// alt: rtf.rtfPointBody switches to the point font on `bold`, so for points
// `bold` IS the emphasis switch.
function _fitSegFmt(s, type) {
  const emph = type === 'point' ? !!s.bold : !!s.alt;
  return { emph, bold: type === 'point' ? false : !!s.bold, italic: !!s.italic, underline: !!s.underline };
}

// One word's measurement HTML — its segments with no spaces between them.
function _fitWordHtml(wd) {
  return wd.segs.map(g => {
    let h = esc(g.mtext ?? g.text);
    if (g.fmt.underline) h = `<u>${h}</u>`;
    if (g.fmt.italic)    h = `<em>${h}</em>`;
    if (g.fmt.bold)      h = `<b>${h}</b>`;
    if (g.fmt.emph)      h = `<strong>${h}</strong>`;
    return h;
  }).join('');
}

// Render the word list at a given box width and read back the actual line
// breakdown (which words landed on which line, and each line's pixel width).
function _fitLinesAtWidth(inner, words, w) {
  inner.style.whiteSpace = 'normal';
  inner.style.display    = 'block';
  inner.style.width      = `${w}px`;
  inner.innerHTML = words.map((wd, i) => `<span class="_fw" data-i="${i}">${_fitWordHtml(wd)}</span>`).join(' ');

  const els   = inner.querySelectorAll('span._fw');
  const lines = [];
  let cur = null, lastTop = null;
  els.forEach((el, i) => {
    const top = el.offsetTop;
    if (lastTop === null || Math.abs(top - lastTop) > 1) {
      cur = { words: [], left: Infinity, right: 0 };
      lines.push(cur);
      lastTop = top;
    }
    cur.words.push(words[i]);
    cur.left  = Math.min(cur.left,  el.offsetLeft);
    cur.right = Math.max(cur.right, el.offsetLeft + el.offsetWidth);
  });
  for (const ln of lines) ln.width = Math.max(0, ln.right - ln.left);
  return lines;
}

// Score a line breakdown. Lower is better; returns Infinity if disqualified.
// Line count plays NO role here — computeOptimalBodyWidth only ever calls
// this on candidates that already share the tier's line count, so every term
// below is purely about which of those equally-tall layouts reads best.
function _fitScore(lines, words, boxW) {
  const W = FIT_WEIGHTS;
  const n = lines.length;
  if (!n) return Infinity;
  if (n > W.maxLines) return Infinity;
  // Hard constraint: a single word wider than the box (guaranteed overflow).
  for (const ln of lines) if (ln.width > boxW + 1) return Infinity;

  let cost = 0;

  // Where each internal break lands (rate by the punctuation it follows), plus
  // a penalty on ANY line — internal or last — that ends on a bare function
  // word like "and" / "the" / "with", with no punctuation of its own to
  // justify it.
  for (let i = 0; i < n; i++) {
    const lw = lines[i].words[lines[i].words.length - 1];
    if (i < n - 1) {
      cost += lw.punctRank === 3 ? W.breakSentence
            : lw.punctRank === 2 ? W.breakClauseMark
            : lw.punctRank === 1 ? W.breakDash
            :                       W.breakMidClause;
    }
    if (lw.runt) cost += W.lineEndFunction;
  }

  // Orphan / widow: a lone short word stranded on the final line.
  if (n > 1) {
    const last = lines[n - 1];
    if (last.words.length === 1) {
      const letters = last.words[0].text.replace(/[^A-Za-z0-9]/g, '').length;
      if (letters <= W.orphanMaxChars) cost += W.orphan;
    }
  }

  // Splitting an emphasis phrase across lines — only meaningful when the block
  // is NOT entirely bold (a fully-bold point has no "highlight" to protect).
  if (!words.every(w => w.emph)) {
    const lineOf = new Map();
    lines.forEach((ln, li) => ln.words.forEach(w => lineOf.set(w, li)));
    let i = 0;
    while (i < words.length) {
      if (words[i].emph) {
        let j = i; while (j < words.length && words[j].emph) j++;
        const a = lineOf.get(words[i]), b = lineOf.get(words[j - 1]);
        if (a !== undefined && b !== undefined && b > a) cost += W.highlightSplit * (b - a);
        i = j;
      } else i++;
    }
  }

  // Reward evenly-filled lines across the whole block — every type now, not
  // just points. This is what makes a widow like "Great" ending a line cost
  // something even for scripture: leaving it alone on a short last line
  // widens the variance across the block.
  if (n > 1) {
    const ws   = lines.map(l => l.width);
    const mean = ws.reduce((a, b) => a + b, 0) / n;
    const varc = ws.reduce((a, b) => a + (b - mean) * (b - mean), 0) / n;
    cost += Math.sqrt(varc) * W.raggedPerPx;
  }

  return cost;
}

// Measure one line's pixel width at no-wrap.
function _fitLineWidth(inner, lineWords) {
  inner.style.whiteSpace = 'nowrap';
  inner.style.display    = 'inline-block';
  inner.style.width      = 'auto';
  inner.innerHTML = lineWords.map(_fitWordHtml).join(' ');
  return inner.scrollWidth;
}

// PostScript font-name suffix ("ExtraBold", "Medium", "Black", ...) → the
// numeric CSS font-weight it actually represents. The measurement DOM used to
// assume every row was Montserrat at a fixed weight (500, or 900 for points)
// regardless of what font the scheme actually named — this is what lets it
// measure at the real weight instead.
const _FIT_WEIGHT_MAP = {
  thin: 100, hairline: 100, extralight: 200, ultralight: 200, light: 300,
  regular: 400, normal: 400, book: 400, roman: 400,
  medium: 500, semibold: 600, demibold: 600, bold: 700,
  extrabold: 800, ultrabold: 800, black: 900, heavy: 900,
};
function _fitFontWeightStyle(psName) {
  const { style } = parseFontPS(psName || '');
  const norm = (style || '').toLowerCase().replace(/[\s_-]/g, '');
  const italic = /italic|oblique/.test(norm);
  const weight = _FIT_WEIGHT_MAP[norm.replace(/italic|oblique/g, '')] || 400;
  return { weight, italic };
}

// Resolve the CSS a row actually renders at — family, weight, italic, and
// letter spacing — from the scheme's own font choice + FontAdv. Previously
// none of this reached the measurement: character spacing was never applied
// at all, and font family/weight/italic were guessed from `type` instead of
// read from the scheme, so a Point row set to a lighter weight than the
// hardcoded 900 measured narrower than what ProPresenter actually draws.
// Capitalization is NOT handled here — see _fitCaseText below, applied to the
// actual characters, since Title Case needs to both capitalize and lowercase
// within one string, which no single CSS text-transform value can express.
function _fitFontDescriptor(fontName, adv) {
  const a = adv || FONT_ADV_DEFAULTS();
  const { family } = parseFontPS(fontName || '');
  const { weight: styleWeight, italic: styleItalic } = _fitFontWeightStyle(fontName);
  const weight = a.bold ? Math.max(styleWeight, 700) : styleWeight;
  const italic = !!(a.italic || styleItalic);
  return {
    // Try the exact PostScript name first (matches a locally-installed static
    // weight file directly, e.g. "Montserrat-Black" as its own family); fall
    // back to the bare family + numeric weight for the Google-Fonts-loaded case.
    fontFamily: `"${fontName || family || 'Montserrat'}", "${family || 'Montserrat'}", sans-serif`,
    bareFamily: family || 'Montserrat',
    fontWeight: String(weight),
    fontStyle: italic ? 'italic' : 'normal',
    letterSpacing: `${a.charSpacing || 0}px`,
    // 'smallCaps' has no reachable UI control (dropped from the capitalization
    // picker) but is kept here as a harmless fallback for any legacy saved value.
    fontVariant: a.capitalization === 'smallCaps' ? 'small-caps' : 'normal',
    cap: a.capitalization || '',
  };
}
function _fitApplyDescriptor(styleObj, d) {
  styleObj.fontFamily    = d.fontFamily;
  styleObj.fontWeight    = d.fontWeight;
  styleObj.fontStyle     = d.fontStyle;
  styleObj.letterSpacing = d.letterSpacing;
  styleObj.fontVariant   = d.fontVariant;
}
function _fitDescriptorCss(d) {
  return `font-family:${d.fontFamily};font-weight:${d.fontWeight};font-style:${d.fontStyle};`
       + `letter-spacing:${d.letterSpacing};font-variant:${d.fontVariant}`;
}

// Real font metrics for Auto Title Y (see estimateTitleY in builder.js), in
// the row's resolved font/weight/style/size — builder.js has no DOM, so these
// have to be measured here and threaded through the spec alongside bodyLines.
// `ascent`/`descent` are the font's own line-box metrics (fontBoundingBox*,
// content-independent); `capAscent` is the actual ink-top of a reference
// capital "H" in this exact font — cap height, not the ink top of the real
// first line's string. Measuring the real string would make a line starting
// "The" sit ~7px lower than one starting "were" (a constant gap, but a title
// that jitters down the deck); cap height adapts to font/weight/capitalization
// while landing every line identically.
function _fitFontMetrics(desc, size) {
  const canvas = _fitFontMetrics._canvas || (_fitFontMetrics._canvas = document.createElement('canvas'));
  const ctx = canvas.getContext('2d');
  ctx.font = `${desc.fontStyle === 'italic' ? 'italic ' : ''}${desc.fontWeight} ${size}px ${desc.fontFamily}`;
  const line = ctx.measureText('Hg');
  const cap  = ctx.measureText('H');
  return {
    ascent:    line.fontBoundingBoxAscent  ?? size * 0.9,
    descent:   line.fontBoundingBoxDescent ?? size * 0.2,
    capAscent: cap.actualBoundingBoxAscent ?? size * 0.7,
  };
}

// Resolve the scheme, row typography, and width ceiling for a Fit Width
// search — shared by computeOptimalBodyWidth (the real DOM measurement) and
// _fitHash (a cheap fingerprint used to decide whether a cached result is
// stale, with none of the expensive part). Splitting this out guarantees the
// two always agree on what a Fit Width result actually depends on.
function _fitResolveContext(rs, type, display, spans = null) {
  // Resolve the scheme so inherited body width / sizes are real numbers, not
  // nulls — otherwise the cap silently falls back to the full canvas and the
  // measurement font size is wrong (the two long-standing Fit Width bugs).
  const st = styleForExport(rs || activeStyleScheme()) || {};
  const isProp  = display === 'prop';
  const canvasW = isProp ? (st.propCanvasW ?? 3200) : (st.canvasW ?? 1920);
  const size    = isProp
    ? (type === 'point' ? (st.propPointSize ?? st.propBodySize ?? 80) : (st.propBodySize ?? 80))
    : (type === 'point' ? (st.pointSize ?? st.bodySize ?? 44) : (st.bodySize ?? 44));
  // Width ceiling: stay within the palette's own configured box for the
  // element being measured — body width for scripture, point width for
  // points — never wider than that regardless of how short the text is.
  const cap     = (isProp
    ? (type === 'point' ? st.propPointW : st.propBodyW)
    : (type === 'point' ? st.pointW     : st.bodyW)) || canvasW;
  const boxW    = Math.max(1, Math.min(cap, canvasW));
  // Resolve the real per-row typography (family/weight/italic/capitalization/
  // character spacing) for the base text and for bold spans, instead of a
  // fixed Montserrat-at-a-guessed-weight assumption — see _fitFontDescriptor.
  const baseFontField = type === 'point' ? (isProp ? 'propPointFont' : 'pointFont')
                                          : (isProp ? 'propBodyFont'  : 'bodyFont');
  const baseAdvField  = type === 'point' ? (isProp ? 'propPointFontAdv' : 'pointFontAdv')
                                          : (isProp ? 'propBodyFontAdv'  : 'bodyFontAdv');
  const boldFontField = isProp ? 'propBoldFont'    : 'boldFont';
  const boldAdvField  = isProp ? 'propBoldFontAdv' : 'boldFontAdv';
  // The row's own advanced styling — points fall back to the bold row, same
  // as builder.js/buildProp.js do when they write the element.
  const adv = st[baseAdvField] || (type === 'point' ? st[boldAdvField] : null) || {};
  let baseDesc, boldDesc;
  if (type === 'point') {
    // Mirror rtf.rtfPointBody: a point is drawn entirely in the point font
    // unless it genuinely mixes bold and plain words, in which case plain
    // words use the body font and bold words the point font with \b.
    // Measuring a plain point in the bold row's font sized the box for text
    // Pro7 never draws whenever the point and bold fonts differ.
    const bodyFontField = isProp ? 'propBodyFont' : 'bodyFont';
    const bodyAdvField  = isProp ? 'propBodyFontAdv' : 'bodyFontAdv';
    baseDesc = _fitPointMixed(spans)
      ? _fitFontDescriptor(st[bodyFontField], st[bodyAdvField])
      : _fitFontDescriptor(st[baseFontField] || st[boldFontField], adv);
    boldDesc = _fitFontDescriptor(st[baseFontField] || st[boldFontField], { ...adv, bold: true });
  } else {
    baseDesc = _fitFontDescriptor(st[baseFontField], st[baseAdvField]);
    boldDesc = _fitFontDescriptor(st[boldFontField] || st[baseFontField], st[boldAdvField] || st[baseAdvField]);
  }
  // Left/right text margins sit inside the box: Pro7 wraps at box width minus
  // both, so the search runs on that inner width and adds them back after.
  const fbL = isProp ? 0 : type === 'point' ? (st.pointMarginLeft ?? st.bodyMarginLeft) : st.bodyMarginLeft;
  const fbR = isProp ? 0 : type === 'point' ? (st.pointMarginRight ?? st.bodyMarginRight) : st.bodyMarginRight;
  const marginL = Math.max(0, adv.marginLeft  ?? fbL ?? 0);
  const marginR = Math.max(0, adv.marginRight ?? fbR ?? 0);
  const maxW    = Math.max(1, boxW - marginL - marginR);
  // Where the Styles box sits, so a fitted box shrinks inside it instead of
  // re-centering on the canvas (an off-centre box used to jump to the middle).
  const palX = isProp
    ? (type === 'point' ? (st.propPointX ?? st.propBodyX) : st.propBodyX)
    : (type === 'point' ? (st.pointX ?? st.bodyX) : st.bodyX);
  const align = adv.alignment || 'center';
  // Box height and top/bottom margins exactly as the element is written
  // (builder.js makeBodyElement/makePointBodyElement, buildProp.js), so
  // `maxLines` below is how many lines Pro7 can show before it scales the
  // font down to fit.
  const boxH = isProp
    ? (type === 'point' ? (st.propPointH ?? st.propBodyH ?? 350.02) : (st.propBodyH ?? 350.02))
    : (type === 'point' ? (st.pointH ?? st.bodyH ?? 100) : (st.bodyH ?? 100));
  const fbT = isProp ? 0 : type === 'point' ? (st.pointMarginTop ?? st.bodyMarginTop ?? 0) : (st.bodyMarginTop ?? 0);
  const fbB = isProp ? (type === 'point' ? 0 : 60)
            : type === 'point' ? (st.pointMarginBottom ?? st.bodyMarginBottom ?? 60) : (st.bodyMarginBottom ?? 0);
  const innerH = Math.max(0, boxH - (adv.marginTop ?? fbT) - (adv.marginBottom ?? fbB));
  const lineHeight = adv.lineHeight ?? 1;
  return { st, isProp, canvasW, size, maxW, boxW, marginL, marginR, palX: palX ?? null, align, baseDesc, boldDesc, innerH, lineHeight };
}

// How many lines of this row fit in its box at full size (see ctx.innerH).
function _fitMaxLines(ctx, metrics) {
  const lineH = (metrics.ascent + metrics.descent) * ctx.lineHeight;
  return lineH > 0 ? Math.max(1, Math.floor((ctx.innerH + 1) / lineH)) : Infinity;
}

// True when a point's spans genuinely mix bold and plain words — the only
// case rtf.rtfPointBody draws in two fonts. Whitespace-only spans (the '\n'
// a hard break inserts) don't count either way.
function _fitPointMixed(spans) {
  const real = (spans || []).filter(s => s && s.text && s.text.trim());
  return real.some(s => s.bold) && real.some(s => !s.bold);
}

// Real font metrics for the title/reference bar's own font — needed because
// the title box's verticalAlignment is usually MIDDLE, not BOTTOM: when the
// box (titleH) is taller than the title's own single line of text, the ink
// sits centered inside it, not flush with the box's bottom edge. estimateTitleY
// (builder.js) needs the title's real line-box height (ascent+descent) to know
// how far the ink actually sits from the box edges — assuming ink==box was the
// source of the "constant offset" title-Y bug on any scheme whose titleH isn't
// already sized close to the title font's own line height. `display` selects
// Display 1's title font/size or Display 2's (propTitleFont/propTitleSize),
// exactly like _fitResolveContext does for the body font.
function _fitTitleMetrics(rs, display) {
  const st = styleForExport(rs || activeStyleScheme()) || {};
  const isProp = display === 'prop';
  const font = (isProp ? st.propTitleFont : st.titleFont) || 'Arial';
  const adv  = (isProp ? st.propTitleFontAdv : st.titleFontAdv) || null;
  const size = (isProp ? st.propTitleSize : st.titleSize) || (isProp ? 110 : 60);
  const desc = _fitFontDescriptor(font, adv);
  const m = _fitFontMetrics(desc, size);
  return { ascent: m.ascent, descent: m.descent };
}

// A deterministic fingerprint of everything that can change a Fit Width
// result: the spans' own content/formatting, both rows' resolved typography,
// the font size, and the box-width ceiling. Used to decide at export whether
// a slide's cached bodyW/bodyLines/etc. are still trustworthy — a stale
// cache (text edited, scheme's font/weight/capitalization changed, or the
// Styles width changed, all without Fit Width re-running) doesn't show up
// as `null`, so a plain "recompute when null" check misses it. Not a
// cryptographic hash — a plain, fast, collision-safe-enough string key is
// all a same-session staleness check needs.
function _fitHash(spans, ctx) {
  // Every span flag that changes how wide the text draws — alt (emphasis
  // font + its capitalization) included: leaving it out meant marking words
  // ALT after a fit kept the old, too-narrow box (and Pro7 wrapped an extra line).
  const spanKey = (spans || []).map(s => `${s.text || ''}|${!!s.bold}|${!!s.alt}|${!!s.italic}|${!!s.underline}|${!!s.super}`).join('');
  const descKey = d => `${d.fontFamily}|${d.fontWeight}|${d.fontStyle}|${d.letterSpacing}|${d.fontVariant}|${d.cap}`;
  return [spanKey, descKey(ctx.baseDesc), descKey(ctx.boldDesc), ctx.size, ctx.maxW,
          ctx.marginL, ctx.marginR, ctx.palX, ctx.boxW, ctx.align, FIT_REV].join('');
}

// What _fitHash WOULD compute for this slide's current spans/scheme right
// now, for `display` — cheap (typography + width-ceiling resolution only,
// none of computeOptimalBodyWidth's DOM sweep), so it's safe to call on
// every fitWidth slide at export just to decide whether a real recompute is
// even needed. Only single-mode point and scripture have a well-defined
// single hash (revealing points share one box across a whole bullet
// sequence — no single result to fingerprint, so they're always recomputed,
// same as before this existed).
function _fitCurrentBodyHash(slide, scheme, display) {
  const isProp = display === 'prop';
  if (slide.type === 'scripture') {
    if (isProp) {
      const spans = scriptureLedSpans(slide);
      return _fitHash(spans, _fitResolveContext(scheme, 'scripture', display, spans));
    }
    // Every main-screen part is fitted, so any part's edit makes it stale.
    return (slide.bodies || [[]]).map(raw => {
      const spans = slide.stripNewlines ? stripNewlineSpans(raw || []) : (raw || []);
      return _fitHash(spans, _fitResolveContext(scheme, 'scripture', display, spans));
    }).join('\x03');
  }
  if (slide.type === 'point' && slide.mode !== 'revealing') {
    // Split mode: Display 2 (prop) has its own independent text, so its
    // staleness hash must depend on propBodyText, not bodyText — otherwise
    // editing one field wouldn't correctly invalidate/preserve the other's cache.
    const text = (isProp && slide.mode === 'split') ? (slide.propBodyText || '') : (slide.bodyText || '');
    const spans = [{ text, bold: true }];
    return _fitHash(spans, _fitResolveContext(scheme, 'point', display, spans));
  }
  return null;
}

// Apply a FontAdv capitalization setting to actual characters, matching what
// ProPresenter renders — not CSS text-transform, which can't express "Title
// Case" (capitalize each word AND lowercase the rest in the same string; the
// old `capitalize` mapping left the remainder in whatever case was typed).
// `startCase`'s exact rule (e.g. minor-word exceptions) isn't documented
// anywhere accessible here, so it gets the same normalization as titleCase
// rather than a guessed-at distinct one — closer to correct than the old
// blanket `capitalize`, and `allLower` — previously unhandled entirely, so a
// row set to All Lower measured at whatever case the text was typed in —
// now actually lowercases.
function _fitCaseText(text, cap) {
  if (!text) return text;
  if (cap === 'allCaps')  return text.toUpperCase();
  if (cap === 'allLower') return text.toLowerCase();
  if (cap === 'titleCase' || cap === 'startCase') {
    return text.toLowerCase().replace(/\b[a-z]/g, c => c.toUpperCase());
  }
  return text;
}

// Guard used before trusting a cached _fitBrokenText against the live
// bodyText at export (collapsing the hard breaks back to spaces should
// reproduce the original text exactly, or the cache is stale and gets
// dropped). Case-insensitive on purpose: a mismatch here should only ever
// mean a stale cache, never a legitimate signal, so it shouldn't be able to
// fail merely because a row's capitalization setting cased the two sides
// differently upstream.
function _fitTextsMatch(a, b) {
  // Whitespace-insensitive too: Fit Width tokenizes on any run of spaces or
  // newlines, so text with a double space or a Strip-removed line break
  // could never match and its hard breaks were silently dropped.
  const norm = t => String(t || '').replace(/\s+/g, ' ').trim().toLowerCase();
  return norm(a) === norm(b);
}

// Enumerate line partitions that break ONLY after punctuation words (comma,
// clause, or sentence end). These reach layouts that box-width alone can't —
// e.g. a point split cleanly after every comma — and are the candidates that,
// when they win, get emitted as hard line breaks. Points only.
function _fitPunctPartitions(words) {
  const breaks = [];
  for (let i = 0; i < words.length - 1; i++) if (words[i].punctRank >= 1) breaks.push(i);
  if (!breaks.length || breaks.length > 6) return [];   // cap: 2^6 subsets
  const partitions = [];
  const total = 1 << breaks.length;
  for (let mask = 1; mask < total; mask++) {
    const cuts = [];
    for (let b = 0; b < breaks.length; b++) if (mask & (1 << b)) cuts.push(breaks[b]);
    if (cuts.length + 1 > FIT_WEIGHTS.maxLines) continue;
    const lines = [];
    let start = 0;
    for (const c of cuts) { lines.push(words.slice(start, c + 1)); start = c + 1; }
    lines.push(words.slice(start));
    partitions.push(lines);
  }
  return partitions;
}

// Rebuild a spans array — preserving each word's bold/italic/underline —
// from the tokenized `words` list (see _fitWordList) and a winning layout's
// per-line word count, with a literal '\n' span inserted between lines.
// Shared by scripture and point: a hard-break layout used to be flattened to
// a plain string (best.broken.join('\n')) and handed to rtf.js as one
// non-bold span, which silently dropped bold formatting on any slide where a
// punctuation-partition layout won — including points, which already had
// this bug before scripture could hit it too. Uses word.text (the real,
// original-case string), never word.mtext — mtext exists only to render
// capitalization into the measurement DOM and must never reach output (see
// the note on _fitWordList).
function _fitSpansFromWinningLayout(words, lineWordCounts) {
  const out = [];
  // Each piece keeps its source span's own properties (alt, bold, italic,
  // underline, verseNum, super, ...) — only the text changes. A separator
  // (space or the line break) takes the formatting of the text before it,
  // minus verse-number/superscript, so an all-emphasis body stays all-emphasis
  // and rtf.js keeps its single-font path.
  const push = (src, text) => {
    const { text: _t, ...props } = src;
    const last = out[out.length - 1];
    const same = last && Object.keys({ ...props, ...last }).every(k => k === 'text' || last[k] === props[k]);
    if (same) last.text += text; else out.push({ ...props, text });
  };
  const sepProps = src => { const { text: _t, verseNum: _v, super: _s, ...rest } = src; return rest; };
  let idx = 0, prevSrc = null;
  lineWordCounts.forEach((count, li) => {
    if (li > 0) push({ ...sepProps(prevSrc || {}), text: '' }, '\n');
    for (let k = 0; k < count; k++) {
      const w = words[idx++];
      if (k > 0) push({ ...sepProps(prevSrc || {}), text: '' }, ' ');
      for (const g of w.segs) { push(g.src, g.text); prevSrc = g.src; }
    }
  });
  return out;
}

// Hidden measurement container in 1:1 canvas pixels, styled as the row
// renders: base font on the container, the emphasis (alt) font on <strong>,
// a plain \b as the current font's bold weight on <b>. Caller removes `msr`.
function _fitMeasurer(ctx) {
  const { size, baseDesc, boldDesc } = ctx;
  const boldOf = d => String(Math.max(Number(d.fontWeight) || 400, 700));
  const msr   = document.createElement('div');
  const style = document.createElement('style');
  style.textContent = `._msr strong{${_fitDescriptorCss(boldDesc)}}._msr b{font-weight:${boldOf(baseDesc)}}`
    + `._msr strong b,._msr b strong{font-weight:${boldOf(boldDesc)}}._msr em{font-style:italic}._msr ._fw{display:inline}`;
  const inner = document.createElement('div');
  inner.className = '_msr';
  msr.appendChild(style);
  msr.appendChild(inner);
  Object.assign(msr.style, {
    position: 'fixed', top: '-9999px', left: '-9999px',
    visibility: 'hidden', pointerEvents: 'none',
    fontSize: `${size}px`,
    lineHeight: '1.3',
  });
  _fitApplyDescriptor(msr.style, baseDesc);
  document.body.appendChild(msr);
  return { msr, inner };
}

// Split spans into paragraphs at explicit newlines (each a spans array).
function _fitParagraphs(spans) {
  const paras = [[]];
  for (const span of (spans || [])) {
    String(span.text || '').split('\n').forEach((part, i) => {
      if (i > 0) paras.push([]);
      if (part) paras[paras.length - 1].push({ ...span, text: part });
    });
  }
  return paras;
}

/**
 * Measure text spans in a hidden div and find the optimal body width.
 * Poetry mode (has \n): tightest width that fits each explicit line no-wrap.
 * Balance mode (no \n): sweep candidate widths, score the induced line break,
 *   pick the lowest-cost layout (see FIT_WEIGHTS) among candidates that share
 *   the floor line count — see the tiering note inside the function.
 * `type` selects the render size/weight ('point' → pointSize + bold).
 * `display` selects which screen's metrics to measure at: 'main' (Display 1)
 *   or 'prop' (Display 2 / LED wall) — these have independent canvas size,
 *   font size, and body-width ceiling, so a box fit for one is not fit for
 *   the other and each needs its own search.
 * The search also proposes explicit punctuation-break layouts (any type, not
 *   just points); when one wins and box-width can't reproduce it, `brokenText`
 *   carries the flattened text and `brokenSpans` the same layout as real spans
 *   (bold/italic/underline preserved per word) for the caller to export.
 * `lines` is the real measured line count the winning width actually wraps
 *   into — used for Auto Title Y instead of a separate, disagreement-prone
 *   estimate.
 * Returns { bodyW, bodyX, brokenText, brokenSpans, lines, ascent, descent,
 * capAscent } in Pro7 canvas coordinates — ascent/descent/capAscent are the
 * base row's real font metrics (see _fitFontMetrics), fed to Auto Title Y
 * alongside `lines` since builder.js has no DOM to measure them itself.
 */
function computeOptimalBodyWidth(spans, rs, type = 'body', display = 'main') {
  // Resolve the scheme, row typography, and width ceiling — shared with the
  // cheap staleness check at export (_fitCurrentHash) so both always agree
  // on what a Fit Width result depends on. See _fitResolveContext.
  const ctx = _fitResolveContext(rs, type, display, spans);
  const { canvasW, size, maxW, boxW, marginL, marginR, palX, align, baseDesc, boldDesc } = ctx;
  const padding = 80; // breathing room for the poetry branch
  // Slack between the longest line and the box edge. Chromium and CoreText
  // agree to within a few px, but a box fitted with 0–3px to spare (what the
  // narrowest-width sweep used to produce) wraps a word in Pro7 at the first
  // rendering difference — kerning, stroke, a font build. Scales with size.
  const pad = Math.max(FIT_WEIGHTS.pad, Math.round(size * FIT_WEIGHTS.padPerPt));

  const hasExplicit = (spans || []).some(s => s.text?.includes('\n'));
  // `lines` is the REAL measured line count at the winning width — Auto Title Y
  // uses this instead of independently re-guessing it from a char-width
  // heuristic, which routinely disagreed with what Fit Width actually rendered.
  // `metrics` (ascent/descent/capAscent) and `fitHash` (staleness fingerprint,
  // see _fitHash) are assigned right below, before `centered` is ever called.
  let metrics = null, fitHash = null, maxLines = Infinity;
  // `w` is the text width; the box adds the row's left/right margins back on
  // and sits inside the Styles box per the row's alignment (centred on that
  // box, not on the canvas, so an off-centre layout keeps its position).
  const centered = (w, brokenText = null, lines = null, brokenSpans = null) => {
    const bw = Math.min(Math.round(w + marginL + marginR), boxW);
    const left = palX ?? Math.round((canvasW - boxW) / 2);
    let bx = align === 'left' ? left : align === 'right' ? left + boxW - bw : left + (boxW - bw) / 2;
    bx = Math.round(Math.max(0, Math.min(bx, canvasW - bw)));
    return { bodyW: bw, bodyX: bx, brokenText, brokenSpans, lines, fitHash, maxLines, ...metrics };
  };

  metrics = _fitFontMetrics(baseDesc, size);
  fitHash = _fitHash(spans, ctx);
  // A plain point is drawn entirely in the point font, never bolded (see
  // _fitResolveContext) — measure it that way too.
  if (type === 'point' && !_fitPointMixed(spans)) spans = (spans || []).map(s => ({ ...s, bold: false }));
  const fmtType = type === 'point' ? 'point' : 'body';
  // Capitalization is applied only to what gets *rendered* into the
  // measurement DOM (each segment's `mtext`, see
  // _fitWordList) — never to `spans`/`words[].text` themselves. Those flow
  // into best.broken → slide._fitBrokenText → bodyDisplayText at export,
  // where a case-transformed value would fail the equality guard against the
  // real bodyText and silently discard the hard breaks Fit Width just found.

  // computeOptimalBodyWidth is synchronous and can't await a font load — if a
  // weight/style combo this row needs hasn't finished loading yet (Google
  // Fonts fetches a specific weight only once something actually renders at
  // it), Chromium silently measures against the fallback font instead. Warn
  // rather than fail silently; the boot-time load below should make this rare.
  for (const d of [baseDesc, boldDesc]) {
    const spec = `${d.fontStyle === 'italic' ? 'italic ' : ''}${d.fontWeight} ${size}px "${d.bareFamily}"`;
    if (document.fonts && !document.fonts.check(spec)) {
      console.warn(`[Fit Width] "${d.bareFamily}" ${spec.split(' ').slice(0, -2).join(' ')} isn't loaded yet — this measurement may be against a fallback font.`);
    }
  }

  const { msr, inner } = _fitMeasurer(ctx);
  maxLines = _fitMaxLines(ctx, metrics);

  try {
    if (hasExplicit) {
      // Poetry: keep the explicit lines; the box fits the widest one. A line
      // longer than the box still wraps, so count each paragraph's real
      // wrapped lines at the chosen width (not just one per explicit line).
      const paras = _fitParagraphs(spans)
        .map(p => _fitWordList(p, baseDesc.cap, boldDesc.cap, fmtType)).filter(w => w.length);
      inner.style.whiteSpace = 'nowrap';
      inner.style.display    = 'inline-block';
      let widest = 0;
      for (const words of paras) {
        inner.innerHTML = words.map(_fitWordHtml).join(' ');
        widest = Math.max(widest, inner.scrollWidth);
      }
      const width = Math.min(Math.ceil(widest) + padding, maxW);
      const count = w => paras.reduce((n, words) => n + _fitLinesAtWidth(inner, words, w).length, 0) || 1;
      return { ...centered(width, null, count(width)), staticLines: count(maxW) };
    }

    // ── Balance mode: weighted candidate search ──
    const words = _fitWordList(spans, baseDesc.cap, boldDesc.cap, fmtType);
    if (!words.length) return { ...centered(maxW), staticLines: null };

    // Floor: never narrower than the widest single word (would force overflow).
    let widestWord = 0;
    inner.style.whiteSpace = 'nowrap';
    inner.style.display    = 'inline-block';
    for (const wd of words) {
      inner.innerHTML = _fitWordHtml(wd);
      widestWord = Math.max(widestWord, inner.scrollWidth);
    }
    const floorW = Math.min(Math.ceil(widestWord) + 4, maxW);
    // Plan every layout within the box minus the slack, so even text that
    // fills the whole Styles box keeps `pad` px spare. Planning right up to
    // the edge let Chromium fit a last word that CoreText (Pro7) wraps — a
    // few px of disagreement became an extra line on screen.
    const planW = Math.max(floorW, maxW - pad);
    // What Pro7 shows when this box ISN'T fitted: its own natural wrap at the
    // full Styles width (Auto Title Y needs that count for unfitted boxes).
    const staticLines = _fitLinesAtWidth(inner, words, maxW).length;

    // Line count is a TIER, not a scored term. Fit Width may only ever
    // shrink the box (the Styles width is a hard ceiling — see the module
    // doc), so the line count the text needs at that full width is the floor:
    // no narrower box can ever produce fewer lines, only the same or more.
    // Only candidates that hit this exact count are ever scored against each
    // other — a two-line layout can no longer out-score a one-line layout by
    // accumulating enough break-quality/evenness credit, because they're
    // never compared to begin with.
    const N = _fitLinesAtWidth(inner, words, planW).length;

    // Sweep widths from floor → maxW; keep the narrowest width that yields each
    // distinct line layout, score it, and track the best. A fine step matters:
    // some strictly-better layouts live in a narrow width window (e.g. shifting
    // a runt "and" down a line), so a coarse sweep would skip right over them.
    const STEP = 12;
    const seen = new Set();
    let best = null;   // { cost, width, broken:string[]|null, lineWordCounts }
    const consider = (lines, boxW, broken, lineWordCounts) => {
      if (lines.length !== N) return;
      const cost = _fitScore(lines, words, boxW);
      if (cost === Infinity) return;
      if (!best || cost < best.cost - 0.01) best = {
        cost, longest: Math.max(...lines.map(l => l.width)),
        lineWordCounts: lineWordCounts || lines.map(l => l.words.length), lineCount: lines.length,
      };
    };
    for (let w = floorW; w <= planW; w += STEP) {
      const lines = _fitLinesAtWidth(inner, words, w);
      const sig = lines.map(l => l.words.length).join(',');
      if (seen.has(sig)) continue;
      seen.add(sig);
      consider(lines, w, null, null);
    }
    // Always consider the full planning-width layout too (covers the single-line case).
    consider(_fitLinesAtWidth(inner, words, planW), planW, null, null);

    // Punctuation-break candidates — layouts that break only after sentence/
    // clause punctuation and can beat anything box-width alone produces. Every
    // type gets these now, not just points (see the tiering note above: with
    // line count no longer a scored term, a partition that adds a line can
    // never win purely by having great break quality — it's excluded by the
    // N-line filter in `consider`, same as any other candidate).
    for (const part of _fitPunctPartitions(words)) {
      if (part.length !== N) continue;
      const lines = part.map(lw => ({ words: lw, width: _fitLineWidth(inner, lw) }));
      consider(lines, planW, lines.map(l => l.words.map(w => w.text).join(' ')), part.map(lw => lw.length));
    }

    if (!best) return { ...centered(maxW, null, N), staticLines };
    // Longest line plus real slack, never past the Styles box.
    const width = Math.min(Math.ceil(best.longest + pad), maxW);
    // The padded box can let a word ride up a line in the natural wrap. Lock
    // the winning layout with hard breaks whenever that happens (or when it's
    // a punctuation layout box width can't reproduce at all) — otherwise
    // box width alone already gives it.
    let brokenText = null, brokenSpans = null;
    const nat = _fitLinesAtWidth(inner, words, width).map(l => l.words.length).join(',');
    if (nat !== best.lineWordCounts.join(',')) {
      brokenSpans = _fitSpansFromWinningLayout(words, best.lineWordCounts);
      let k = 0;
      brokenText = best.lineWordCounts.map(c => words.slice(k, k += c).map(w => w.text).join(' ')).join('\n');
    }
    return { ...centered(width, brokenText, best.lineCount, brokenSpans), staticLines };
  } finally {
    document.body.removeChild(msr);
  }
}

// Strip removes line breaks so the main-screen body flows as one block. Line
// breaks aren't always their own span: extractSpans() merges a <br>'s span into
// the surrounding text whenever the formatting matches on both sides — the
// common case for plain, unformatted scripture — so the break ends up embedded
// inside a longer span's text ("line one\nline two") rather than sitting alone
// as its own {text:'\n'} entry. An exact `s.text !== '\n'` filter only ever
// catches the standalone case, so it silently did nothing for plain text.
// Mirrors builder.js's stripNewlineSpans — keep both in sync.
function stripNewlineSpans(spans) {
  const replaced = (spans || []).map(s => ({ ...s, text: (s.text || '').replace(/\n+/g, ' ') }));
  if (replaced.length) {
    replaced[0] = { ...replaced[0], text: replaced[0].text.replace(/^ +/, '') };
    replaced[replaced.length - 1] = { ...replaced[replaced.length - 1], text: replaced[replaced.length - 1].text.replace(/ +$/, '') };
  }
  return replaced.filter(s => s.text !== '');
}

// What the LED wall shows for a scripture slide: every part at once (its prop
// stays up across all the main-screen parts). slide.partJoins[i] is what goes
// between part i and i+1: "Split for main screen" records whatever was there
// in the passage (a space, or a line break in poetry) so the LED shows it as
// if it was never split; parts split by hand keep a line break, as they
// always have. Mirrors buildScripturePropCue in buildProp.js (spec.propJoins).
function scripturePartJoins(slide) {
  return (slide.bodies || [[]]).slice(1).map((_, i) => (slide.partJoins?.[i] === ' ' ? ' ' : '\n'));
}
function scriptureLedSpans(slide) {
  const joins = scripturePartJoins(slide);
  return (slide.bodies || [[]]).reduce((acc, body, i) => {
    if (i > 0) acc.push({ text: joins[i - 1], bold: false });
    return acc.concat(body || []);
  }, []);
}

// ── Overflow: text taller than its box ──────────────────────────────────────
// Every body/point box is written with SCALE_FONT_DOWN, so when the text needs
// more lines than the box holds Pro7 quietly shrinks the font until it fits.
// DeckPro never shrinks it itself: it warns, and for the main screen offers to
// split the passage into slides that each fit (splitPassageForMain).

// Cheap natural-wrap line counter for one row, sharing one measurement
// container across many calls. `fit`: count at Fit Width's planning width
// (what a fitted box shows), else at the full Styles width.
function _fitLineCounter(scheme, type, display, fit) {
  const ctx = _fitResolveContext(scheme, type, display, null);
  const metrics = _fitFontMetrics(ctx.baseDesc, ctx.size);
  const pad = Math.max(FIT_WEIGHTS.pad, Math.round(ctx.size * FIT_WEIGHTS.padPerPt));
  const width = fit ? Math.max(1, ctx.maxW - pad) : ctx.maxW;
  const fmtType = type === 'point' ? 'point' : 'body';
  const { msr, inner } = _fitMeasurer(ctx);
  return {
    maxLines: _fitMaxLines(ctx, metrics),
    size: ctx.size,
    count(spans) {
      return _fitParagraphs(spans).reduce((n, p) => {
        const words = _fitWordList(p, ctx.baseDesc.cap, ctx.boldDesc.cap, fmtType);
        return n + (words.length ? _fitLinesAtWidth(inner, words, width).length : 0);
      }, 0);
    },
    close() { msr.remove(); },
  };
}

// The part of `spans` between character offsets [a, b) of their joined text,
// formatting kept, outer whitespace trimmed.
function _sliceSpans(spans, a, b) {
  const out = [];
  let pos = 0;
  for (const sp of spans) {
    const t = sp.text || '', s0 = pos, s1 = pos + t.length;
    pos = s1;
    const lo = Math.max(a, s0), hi = Math.min(b, s1);
    if (hi > lo) out.push({ ...sp, text: t.slice(lo - s0, hi - s0) });
  }
  if (out.length) {
    out[0] = { ...out[0], text: out[0].text.replace(/^\s+/, '') };
    const k = out.length - 1;
    out[k] = { ...out[k], text: out[k].text.replace(/\s+$/, '') };
  }
  return out.filter(x => x.text !== '');
}

// Split one passage into the fewest pieces that each fit the main-screen box,
// preferring breaks at sentence ends, then clauses, then dashes, and pieces of
// even length. Returns { pieces: span arrays, joins: what separated each piece
// from the next (' ' or '\n') }, or null when it already fits
// (or no split can make it fit). `strip`: pieces are shown with newlines
// flattened (the slide's Strip setting), so measure them that way.
function splitPassageForMain(spans, scheme, { fit = false, strip = false } = {}) {
  spans = (spans || []).filter(x => x.text);
  const text = spans.map(x => x.text).join('');
  const toks = [...text.matchAll(/\S+/g)].map(m => ({ a: m.index, b: m.index + m[0].length, t: m[0] }));
  if (toks.length < 2) return null;
  // Which characters belong to a verse number — never end a piece on one.
  const verseAt = new Uint8Array(text.length);
  { let pos = 0; for (const sp of spans) { if (sp.verseNum) verseAt.fill(1, pos, pos + sp.text.length); pos += sp.text.length; } }
  const rank = toks.map((tk, i) => {
    if (verseAt[tk.b - 1]) return -1;
    const gap = i + 1 < toks.length ? text.slice(tk.b, toks[i + 1].a) : '';
    if (gap.includes('\n')) return 3;
    const end = tk.t.replace(/["'”’)\]]+$/, '');
    return /[.!?…]$/.test(end) ? 3 : /[:;]$/.test(end) ? 2 : /[,—–-]$/.test(end) ? 1 : 0;
  });
  const ctr = _fitLineCounter(scheme, 'scripture', 'main', fit);
  try {
    const piece = (i, j) => _sliceSpans(spans, toks[i].a, toks[j - 1].b);
    const lines = (i, j) => { const p = piece(i, j); return ctr.count(strip ? stripNewlineSpans(p) : p); };
    const n = toks.length, max = ctr.maxLines;
    if (lines(0, n) <= max) return null;
    const solve = loose => {
      const ends = [];
      for (let j = 1; j < n; j++) if (rank[j - 1] >= (loose ? 0 : 1)) ends.push(j);
      ends.push(n);
      const best = new Array(n + 1).fill(null);
      best[0] = { cost: 0, prev: -1 };
      for (const i of [0, ...ends.slice(0, -1)]) {
        if (!best[i]) continue;
        for (const j of ends) {
          if (j <= i) continue;
          const L = lines(i, j);
          if (L > max) break; // longer pieces from i only get taller
          const r = j < n ? rank[j - 1] : 3;
          const cost = best[i].cost + 1000 + [10, 6, 3, 0][Math.max(0, r)] + 2 * L * L + (j - i <= 2 ? 12 : 0);
          if (!best[j] || cost < best[j].cost) best[j] = { cost, prev: i };
        }
      }
      if (!best[n]) return null;
      const cuts = [];
      for (let j = n; j > 0; j = best[j].prev) cuts.unshift([best[j].prev, j]);
      return {
        pieces: cuts.map(([i, j]) => piece(i, j)),
        // What separated each piece from the next in the passage.
        joins: cuts.slice(0, -1).map(([, j]) => (text.slice(toks[j - 1].b, toks[j].a).includes('\n') ? '\n' : ' ')),
      };
    };
    return solve(false) || solve(true);
  } finally {
    ctr.close();
  }
}

// What overflows on this slide, from its last measurement (storeFitCapacity):
// { main: [{ part, lines, maxLines }], led: { lines, maxLines } | null }.
function slideOverflow(slide) {
  const fit = !!slide.fitWidth, propFit = fit && !!slide.propFitWidth;
  const over = (f, fitted) => {
    if (!f || !f.maxLines) return null;
    const lines = fitted ? (f.lines ?? f.staticLines) : (f.staticLines ?? f.lines);
    return lines > f.maxLines ? { lines, maxLines: f.maxLines } : null;
  };
  if (slide.type === 'scripture') {
    const main = (slide._bodyFits || []).map((f, part) => {
      const o = over(f, fit);
      return o && { part, ...o };
    }).filter(Boolean);
    return { main, led: over(slide._ledFit, propFit) };
  }
  if (slide.type === 'point' && slide.mode !== 'revealing') {
    const o = over(slide._pointFit, fit);
    return { main: o ? [{ part: 0, ...o }] : [], led: null };
  }
  return { main: [], led: null };
}

// Rough size Pro7 shrinks to: fewer points means more words per line AND
// shorter lines, so the needed scale is about √(lines that fit / lines needed).
function overflowShrunkSize(size, o) {
  return Math.max(1, Math.round(size * Math.sqrt(o.maxLines / o.lines)));
}

// Keep what the overflow check needs from a computeSlideFitWidth result:
// scripture's per-part fits (also exported, see buildSpec) and each display's
// line count vs. how many lines its box holds.
function storeFitCapacity(slide, r) {
  if (slide.type === 'scripture') {
    slide._bodyFits = r.bodyFits || null;
    slide._ledFit = { lines: r.propFitLines ?? null, staticLines: r.propStaticLines ?? null, maxLines: r.propMaxLines ?? null };
  } else if (slide.type === 'point' && slide.mode !== 'revealing') {
    slide._pointFit = { lines: r.lines ?? null, staticLines: r.staticLines ?? r.lines ?? null, maxLines: r.maxLines ?? null };
  }
}

// Compute Fit Width for one slide's current text. Single source of truth for
// both the per-slide toggle (attachFormHandlers) and the pre-export batch
// recompute — keeps the two from drifting apart.
//
// Scripture: measures the stripped (newline-free) text when Strip is also on,
// since Strip flattens display 1 into one flowing paragraph — the box should
// fit that paragraph, not the original poetry line lengths. Display 2 (LED
// wall) always keeps the original line breaks regardless of Strip — Strip is
// display-1-only — so its box is measured against the unstripped text.
//
// Display 1 and Display 2 have independent canvas size, font size, and body
// width, so a box fit for one is not fit for the other — each gets its own
// computeOptimalBodyWidth() search (see the `display` param there).
//
// Display 2 is gated behind its OWN flag (slide.propFitWidth) — defaults to
// true on new slides (same as slide.fitWidth), but is a genuinely independent
// flag, not hard-coupled to Display 1's. Coupling them directly (Display 1 on
// ⇒ Display 2 also resized, with no separate flag at all) was tried and
// reverted: Display 2 often carries a deliberately custom box (position/size
// hand-tuned to a specific screen/NDI feed), and silently shrinking +
// recentering it the moment Display 1's Fit Width was turned on broke that
// tuning with no way to opt out. Turn this off per-slide wherever Display 2
// has a hand-tuned box that should be left alone.
//
// Revealing points: every cue in the sequence shares one box per display
// (spec.bodyW/bodyX and spec.propBodyW/propBodyX in builder.js/buildProp.js),
// so each display is sized off its OWN widest individual bullet rather than
// just the first — otherwise a later, longer bullet could overflow a box
// sized for a short one. That keeps each box static across the whole reveal
// sequence.
//
// Returns { bodyW, bodyX, brokenText, bodyLines, propBodyW, propBodyX,
// propBrokenText, propBodyLines } (prop fields null if not applicable) or
// null if there's no text to measure. bodyLines/propBodyLines are the real
// measured line counts, fed to Auto Title Y (see estimateTitleY/
// estimatePropTitleY) instead of that heuristic re-deriving them and
// disagreeing with what Fit Width actually rendered.
function computeSlideFitWidth(slide, scheme) {
  const wantsProp = !!slide.propFitWidth;
  if (slide.type === 'scripture') {
    const bodies = (slide.bodies && slide.bodies.length) ? slide.bodies : [[]];
    const rawSpans = bodies[0] || [];
    if (!rawSpans.length || rawSpans.every(s => !s.text)) return null;
    // Each main-screen part is its own cue with its own box (builder.js reads
    // spec.bodyFits[idx]); part 1's result also fills the legacy body* fields.
    const bodyFits = bodies.map(raw => {
      const spans = slide.stripNewlines ? stripNewlineSpans(raw || []) : (raw || []);
      if (!spans.some(s => (s.text || '').trim())) return null;
      return computeOptimalBodyWidth(spans, scheme, 'scripture', 'main');
    });
    const main = { ...bodyFits[0], fitHash: _fitCurrentBodyHash(slide, scheme, 'main') };
    // Title font metrics (see _fitTitleMetrics) — independent of the body
    // measurement above, but only ever needed alongside it (scripture's title
    // bar), so it's resolved here rather than adding a separate call site.
    const titleM = _fitTitleMetrics(scheme, 'main');
    // Display 2 gets its own independent search against rawSpans (unstripped —
    // Strip is a Display-1-only setting) — never derived from Display 1's result.
    // Always measured for scripture, even without "+ Display 2": LED-wall Auto
    // Title Y needs the real line count + metrics either way. The line count
    // is the tier N measured at the full Styles width, which IS the static box
    // when the width isn't fitted — so it's exact for that box too.
    // The LED wall shows every part at once, so it's measured on all of them.
    const prop = computeOptimalBodyWidth(scriptureLedSpans(slide), scheme, 'scripture', 'prop');
    const propTitleM = _fitTitleMetrics(scheme, 'prop');
    return {
      ...main, bodyLines: main.lines, titleAscent: titleM.ascent, titleDescent: titleM.descent,
      bodyStaticLines: main.staticLines ?? main.lines,
      bodyFits: bodyFits.map(f => f && {
        bodyW: f.bodyW, bodyX: f.bodyX, lines: f.lines, staticLines: f.staticLines ?? f.lines,
        brokenText: f.brokenText || null, brokenSpans: f.brokenSpans || null, maxLines: f.maxLines,
      }),
      propMaxLines: prop.maxLines, propStaticLines: prop.staticLines ?? prop.lines, propFitLines: prop.lines,
      propBodyW: wantsProp ? prop.bodyW : null, propBodyX: wantsProp ? prop.bodyX : null,
      propBodyLines: wantsProp ? prop.lines : (prop.staticLines ?? prop.lines),
      propBrokenText: wantsProp ? (prop.brokenText || null) : null, propBrokenSpans: wantsProp ? (prop.brokenSpans || null) : null,
      propAscent: prop.ascent, propDescent: prop.descent, propCapAscent: prop.capAscent,
      propTitleAscent: propTitleM.ascent, propTitleDescent: propTitleM.descent,
      propFitHash: _fitCurrentBodyHash(slide, scheme, 'prop'),
    };
  }
  if (slide.type === 'point') {
    if (slide.mode === 'revealing') {
      let best = null, bestProp = null;
      for (const bullet of (slide.bullets || [])) {
        const spans = Array.isArray(bullet) ? bullet : [{ text: bullet || '', bold: true }];
        if (!spans.length || spans.every(s => !s.text)) continue;
        const r = computeOptimalBodyWidth(spans, scheme, 'point', 'main');
        if (!best || r.bodyW > best.bodyW) best = r;
        if (wantsProp) {
          const rp = computeOptimalBodyWidth(spans, scheme, 'point', 'prop');
          if (!bestProp || rp.bodyW > bestProp.bodyW) bestProp = rp;
        }
      }
      if (!best) return null;
      return { ...best, propBodyW: bestProp ? bestProp.bodyW : null, propBodyX: bestProp ? bestProp.bodyX : null };
    }
    const text = slide.bodyText || '';
    if (!text) return null;
    const spans = [{ text, bold: true }];
    const main = computeOptimalBodyWidth(spans, scheme, 'point', 'main');
    if (!wantsProp) return { ...main, propBodyW: null, propBodyX: null, propBrokenText: null, propBrokenSpans: null, propFitHash: null };
    // Split mode: Display 2 gets its own independent search against its own
    // text (propBodyText) — never derived from Display 1's spans, same as
    // scripture's main/prop split.
    const propSpans = slide.mode === 'split' ? [{ text: slide.propBodyText || '', bold: true }] : spans;
    const prop = computeOptimalBodyWidth(propSpans, scheme, 'point', 'prop');
    return { ...main, propBodyW: prop.bodyW, propBodyX: prop.bodyX, propBrokenText: prop.brokenText || null, propBrokenSpans: prop.brokenSpans || null, propFitHash: prop.fitHash };
  }
  return null;
}

// ─── Macro color helpers ───────────────────────────────────────────────────────

function pro7ColorToCss(c) {
  if (!c) return null;
  return `rgba(${Math.round((c.red||0)*255)},${Math.round((c.green||0)*255)},${Math.round((c.blue||0)*255)},${c.alpha??1})`;
}

function macroDisplayColor(m) {
  if (m.color) return m.color;
  if (pro7rt.liveMacros?.length) {
    const live = pro7rt.liveMacros.find(l => (l.id?.uuid ?? l.id ?? '') === m.uuid);
    const css = pro7ColorToCss(live?.color);
    if (css) return css;
  }
  // Stable hash color from UUID so each macro is visually distinct even offline
  let h = 0;
  const s = m.uuid || m.id || '';
  for (let i = 0; i < s.length; i++) h = (Math.imul(31, h) + s.charCodeAt(i)) | 0;
  return `hsl(${(h >>> 0) % 360},65%,55%)`;
}

// ─── Sidebar ──────────────────────────────────────────────────────────────────

let rcGroupExpanded = false;
const expandedRevealGroups = new Set(); // revealing-point slide ids currently unfurled

const ICON = {
  start:     { cls: 'si-start',     text: 'S'  },
  end:       { cls: 'si-end',       text: 'E'  },
  blank:     { cls: 'si-blank',     text: 'B'  },
  scripture: { cls: 'si-scripture', text: 'S' },
  point:     { cls: 'si-point',     text: 'P' },
  image:     { cls: 'si-image',     text: 'I' },
  custom:    { cls: 'si-custom',    text: 'C' },
  alias:     { cls: 'si-alias-orphan', text: '!' },
};

// ─── Alias slides ────────────────────────────────────────────────────────────
// An alias repeats another slide at a second spot in the deck: same content,
// same prop (no extra prop slot), its own label + blank-before/QR. It stores
// only the source's id — editing the original updates every alias of it.
const ALIAS_SOURCE_TYPES = ['scripture', 'point', 'image'];
const ALIAS_TYPE_NAMES = { scripture: 'Scripture', point: 'Point', image: 'Image' };

function aliasSource(slide) {
  if (slide?.type !== 'alias') return null;
  const src = state.slides.find(s => s.id === slide.aliasOf);
  return src && ALIAS_SOURCE_TYPES.includes(src.type) ? src : null;
}

function aliasDisplayLabel(slide) {
  const src = aliasSource(slide);
  return slide.label?.trim() || (src ? (src.label || ALIAS_TYPE_NAMES[src.type]) : 'Alias (original deleted)');
}

function createAlias(sourceId) {
  const idx = state.slides.findIndex(s => s.id === sourceId);
  const src = state.slides[idx];
  if (!src || !ALIAS_SOURCE_TYPES.includes(src.type)) return;
  const alias = {
    id: uid(), type: 'alias', fixed: false, label: '', aliasOf: src.id,
    blankBefore: !!src.blankBefore, blankSpans: [], qrOverride: null,
  };
  state.slides.splice(idx + 1, 0, alias);
  state.activeId = alias.id;
  saveState(); render();
}

// Stage display entries matching any of the given trigger keys (type + pos) — mirrors getSlideMacroBadges.
function getSlideStageDisplays(...triggerKeys) {
  const displays = activeStyleScheme().stageDisplays || [];
  return displays.filter(d =>
    (d.name || d.uuid) && triggerKeys.some(k => (d.triggers || []).includes(k))
  );
}

// Sidebar: monitor-on-stand dot badges for stage displays firing on these triggers.
// Small QR-square badge for a blank that will fire the QR macro on export —
// same visual family as the macro/stage badges, shown next to them.
function qrBadgeHTML(qrOn) {
  if (!qrOn) return '';
  const QR_ICON = `<svg class="si-qr-icon" viewBox="0 0 10 10" fill="none" xmlns="http://www.w3.org/2000/svg"><rect x="1" y="1" width="3" height="3" rx="0.5" stroke="currentColor" stroke-width="1"/><rect x="6" y="1" width="3" height="3" rx="0.5" stroke="currentColor" stroke-width="1"/><rect x="1" y="6" width="3" height="3" rx="0.5" stroke="currentColor" stroke-width="1"/><rect x="6.5" y="6.5" width="2" height="2" rx="0.3" fill="currentColor"/></svg>`;
  return `<span class="si-badge si-badge-qr" title="QR code fires on this blank">${QR_ICON}</span>`;
}

function stageDisplayBadgesHTML(...triggerKeys) {
  const STAGE_ICON = `<svg class="sd-brush-icon" viewBox="0 0 10 10" fill="none" xmlns="http://www.w3.org/2000/svg"><rect x="2" y="1.3" width="6" height="4.2" rx="0.6" stroke="currentColor" stroke-width="1.1"/><path d="M5 5.5v1.6M3.3 7.9h3.4" stroke="currentColor" stroke-width="1.1" stroke-linecap="round"/></svg>`;
  return getSlideStageDisplays(...triggerKeys)
    .map(d => `<span class="si-badge si-badge-stage" title="Stage: ${esc(d.name || d.uuid)}">${STAGE_ICON}</span>`)
    .join('');
}

// Main panel: monitor-on-stand + name chips for stage displays firing on these triggers.
function stageDisplayChipsHTML(...triggerKeys) {
  const STAGE_ICON = `<svg class="slide-chip-icon" viewBox="0 0 10 10" fill="none" xmlns="http://www.w3.org/2000/svg"><rect x="2" y="1.3" width="6" height="4.2" rx="0.6" stroke="currentColor" stroke-width="1.1"/><path d="M5 5.5v1.6M3.3 7.9h3.4" stroke="currentColor" stroke-width="1.1" stroke-linecap="round"/></svg>`;
  return getSlideStageDisplays(...triggerKeys)
    .map(d => `<span class="slide-macro-chip slide-stage-chip" title="Stage: ${esc(d.name || d.uuid)}">${STAGE_ICON}${esc(d.name || d.uuid)}</span>`)
    .join('');
}

// Returns `pos:N` key for a slide (1-indexed position in state.slides).
function slidePosKey(slide) { return `pos:${state.slides.indexOf(slide) + 1}`; }

// Auto QR default for a blank-before-eligible slide: true only when the
// deck-wide QR toggle (state.config.qrCode) is on AND this slide sits before
// the first Questions marker in the deck (no marker in the deck = everything
// counts as "before").
function autoQRDefault(slide) {
  if (!state.config.qrCode) return false;
  const markerIdx = state.slides.findIndex(s => s.type === 'qrmarker');
  if (markerIdx === -1) return true;
  const slideIdx = state.slides.indexOf(slide);
  return slideIdx !== -1 && slideIdx < markerIdx;
}

// Final QR state for a blank-before-eligible slide. Manual override
// (slide.qrOverride, set by clicking the per-slide QR toggle) always wins
// over the auto default computed from the marker + deck-wide toggle —
// moving the marker later never changes a slide you've already touched by hand.
function effectiveQR(slide) {
  return (slide.qrOverride !== null && slide.qrOverride !== undefined) ? slide.qrOverride : autoQRDefault(slide);
}

// Inline text chips shown in the main panel heading — accepts multiple trigger keys (type + pos).
function macroChipsHTML(...triggerKeys) {
  const macros = activeStyleScheme().macros || [];
  return macros
    .filter(m => triggerKeys.some(k => (m.triggers || []).includes(k)))
    .map(m => `<span class="slide-macro-chip" style="${m.color ? `--mc:${m.color}` : ''}" title="${esc(m.name)}">${esc(m.name)}</span>`)
    .join('');
}

// All macros assigned to any of the given trigger keys (type + pos).
function getSlideMacroBadges(...triggerKeys) {
  const macros = activeStyleScheme().macros || [];
  return macros
    .filter(m => triggerKeys.some(k => (m.triggers || []).includes(k)))
    .map(m => ({ cls: 'macro-assigned', icon: 'dot', color: macroDisplayColor(m), title: m.name }));
}

function macroBadgesHTML(badges) {
  return (badges || []).map(macroBadgeHTML).join('');
}

function macroBadgeHTML(badge) {
  if (!badge) return '';
  const titleAttr = badge.title ? ` title="${esc(badge.title)}"` : '';
  let icon = '';
  if (badge.icon === 'dot')
    icon = `<span class="badge-icon badge-macro-dot"${badge.title ? ` data-name="${esc(badge.title)}"` : ''}${badge.color ? ` style="background:${badge.color}"` : ''}></span>`;
  else if (badge.icon === 'ring')
    icon = `<span class="badge-icon badge-macro-ring"${titleAttr}${badge.color ? ` style="color:${badge.color}"` : ''}></span>`;
  else if (badge.icon === 'circle')       icon = '<span class="badge-icon badge-circle"></span>';
  else if (badge.icon === 'circle-slash') icon = '<span class="badge-icon badge-circle-slash"></span>';
  return `<span class="si-badge si-badge-macro ${badge.cls}">${icon}${badge.text ? esc(badge.text) : ''}</span>`;
}

// Paintbrush + layout name tag for per-slide stage layout overrides.
function stageBadgeHTML(slide) {
  const layout = slide?.stageLayout?.layoutName;
  if (!layout) return '';
  return `<span class="si-badge si-tag si-tag-stage" title="Stage Layout Override: ${esc(layout)}">
    <svg class="si-tag-icon" viewBox="0 0 14 14" fill="none" xmlns="http://www.w3.org/2000/svg">
      <path d="M9.5 2L12 4.5 5.5 11 2 12l1-3.5L9.5 2Z" stroke="currentColor" stroke-width="1.2" stroke-linejoin="round"/>
      <path d="M8 3.5l2.5 2.5" stroke="currentColor" stroke-width="1.2" stroke-linecap="round"/>
    </svg>${esc(layout)}</span>`;
}

// ─── Sidebar item right-click context menu ───────────────────────────────────

let _slideCtxMenu = null;

function getSlideCtxMenu() {
  if (_slideCtxMenu) return _slideCtxMenu;
  _slideCtxMenu = document.createElement('div');
  _slideCtxMenu.id = 'slide-ctx-menu';
  _slideCtxMenu.innerHTML = `
    <button id="ctx-dupe-slide">Duplicate</button>
    <button id="ctx-alias-slide">Create Alias</button>
    <button id="ctx-delete-slide" class="ctx-delete">Delete</button>
  `;
  document.body.appendChild(_slideCtxMenu);
  document.addEventListener('mousedown', e => {
    if (!_slideCtxMenu.contains(e.target)) hideSlideCtxMenu();
  });
  return _slideCtxMenu;
}

function showSlideCtxMenu(x, y, { onDuplicate, onDelete, onAlias }) {
  const menu = getSlideCtxMenu();
  const dupeBtn  = menu.querySelector('#ctx-dupe-slide');
  const aliasBtn = menu.querySelector('#ctx-alias-slide');
  const delBtn   = menu.querySelector('#ctx-delete-slide');
  dupeBtn.style.display  = onDuplicate ? '' : 'none';
  aliasBtn.style.display = onAlias     ? '' : 'none';
  delBtn.style.display   = onDelete    ? '' : 'none';
  dupeBtn.onclick  = onDuplicate ? () => { onDuplicate(); hideSlideCtxMenu(); } : null;
  aliasBtn.onclick = onAlias     ? () => { onAlias();     hideSlideCtxMenu(); } : null;
  delBtn.onclick   = onDelete    ? () => { onDelete();    hideSlideCtxMenu(); } : null;
  menu.style.left = x + 'px';
  menu.style.top  = y + 'px';
  menu.classList.add('open');
  const rect = menu.getBoundingClientRect();
  if (rect.right  > window.innerWidth)  menu.style.left = Math.max(0, x - rect.width)  + 'px';
  if (rect.bottom > window.innerHeight) menu.style.top  = Math.max(0, y - rect.height) + 'px';
}

function hideSlideCtxMenu() {
  _slideCtxMenu?.classList.remove('open');
}

function makeSidebarItem({ id, cls, iconCls, iconText, label, fixed, draggable, onClick, onDelete, onDuplicate, onAlias, macroBadges, stageBadges, transBadge, propTransBadge }) {
  const item = document.createElement('div');
  item.className = `slide-item${cls ? ' ' + cls : ''}${fixed ? ' fixed' : ''}`;
  item.dataset.id = id;
  if (draggable) item.draggable = true;
  const badges = macroBadgesHTML(macroBadges)
               + (stageBadges || '')
               + (transBadge     ? `<span class="si-badge si-badge-trans">${esc(transBadge)}</span>`           : '')
               + (propTransBadge ? `<span class="si-badge si-badge-prop-trans">${esc(propTransBadge)}</span>` : '');
  item.innerHTML = `
    <div class="slide-icon ${iconCls}">${iconText}</div>
    <div class="slide-label">${esc(label)}</div>
    ${badges ? `<div class="slide-badges">${badges}</div>` : ''}
  `;
  item.addEventListener('click', () => onClick());
  if (onDuplicate || onDelete || onAlias) {
    item.addEventListener('contextmenu', e => {
      e.preventDefault();
      showSlideCtxMenu(e.clientX, e.clientY, { onDuplicate, onDelete, onAlias });
    });
  }
  return item;
}

function renderSidebar() {
  const queue = document.getElementById('slide-queue');
  queue.innerHTML = '';

  // Update deck-wide QR toggle button state
  const qrToggleBtn = document.getElementById('btn-deck-qr');
  if (qrToggleBtn) qrToggleBtn.classList.toggle('active', !!state.config.qrCode);
  const slot = state.config.propCollection === 2 ? 2 : 1;
  for (const b of document.querySelectorAll('#deck-slot-seg button')) {
    const on = Number(b.dataset.slot) === slot;
    b.classList.toggle('active', on);
    b.setAttribute('aria-checked', String(on));
  }

  for (let _si = 0; _si < state.slides.length; _si++) {
    const slide = state.slides[_si];
    // Hide blank slides from sidebar when showBlanks is false
    if (!state.showBlanks && slide.type === 'blank') continue;

    // Questions marker: a striped divider, not a real slide — marks where
    // auto QR-fill (deck-wide QR toggle) stops. No form, no export.
    if (slide.type === 'qrmarker') {
      const marker = document.createElement('div');
      marker.className = `slide-item qr-marker-item${slide.id === state.activeId ? ' active' : ''}`;
      marker.dataset.id = slide.id;
      marker.draggable = true;
      marker.innerHTML = `<span class="qr-marker-label">Questions</span>`;
      marker.addEventListener('click', () => selectSlide(slide.id));
      marker.addEventListener('contextmenu', e => {
        e.preventDefault();
        showSlideCtxMenu(e.clientX, e.clientY, {
          onDuplicate: () => duplicateSlide(slide.id),
          onDelete:    () => deleteSlide(slide.id),
        });
      });
      marker.addEventListener('dragstart', onDragStart);
      marker.addEventListener('dragend',   onDragEnd);
      marker.addEventListener('dragover',  onDragOver);
      marker.addEventListener('dragleave', onDragLeave);
      marker.addEventListener('drop',      onDrop);
      queue.appendChild(marker);
      continue;
    }

    const isAlias        = slide.type === 'alias';
    const aliasSrc       = isAlias ? aliasSource(slide) : null;
    // An alias exports as its source's type, so it gets that type's icon + macros
    const effType        = isAlias ? (aliasSrc?.type || 'alias') : slide.type;
    const ic             = ICON[effType] || { cls: '', text: '?' };
    const posKey         = `pos:${_si + 1}`;
    const hasBB          = slide.blankBefore && ['scripture', 'point', 'image', 'alias'].includes(slide.type);
    // pos:N badge goes on the blank-before row (it is the Nth output cue); exclude it from the content slide
    const macroBadges    = getSlideMacroBadges(effType, ...(hasBB ? [] : [posKey]));
    if (slide.macroOverride) {
      macroBadges.push({ cls: 'macro-override', icon: 'ring', color: macroDisplayColor(slide.macroOverride), title: `Override: ${slide.macroOverride.name}` });
    }
    const transBadge     = slide.transition?.type     ? slide.transition.type.toUpperCase()     : null;
    const propTransBadge = slide.propTransition?.type ? slide.propTransition.type.toUpperCase() : null;

    // Blank-before indicator row (before content slides with blankBefore: true)
    if (hasBB) {
      const indicator = document.createElement('div');
      indicator.className = 'si-blank-indicator' + (!state.showBlanks ? ' hidden' : '');
      const bbBadges = getSlideMacroBadges('blankBefore', posKey);
      const bbStageBadges = stageDisplayBadgesHTML('blankBefore', posKey);
      const bbQrBadge = qrBadgeHTML(effectiveQR(slide));
      indicator.innerHTML = `<span class="si-blank-icon"><span class="badge-circle"></span></span><span class="si-blank-label">blank</span><div class="slide-badges" style="margin-left:auto">${macroBadgesHTML(bbBadges)}${bbStageBadges}${bbQrBadge}</div>`;
      queue.appendChild(indicator);
    }

    const item = makeSidebarItem({
      id:          slide.id,
      cls:         [slide.id === state.activeId ? 'active' : '', isAlias ? 'alias-item' : ''].filter(Boolean).join(' '),
      iconCls:     ic.cls,
      iconText:    ic.text,
      label:       isAlias ? aliasDisplayLabel(slide) : slide.label,
      fixed:       slide.fixed,
      draggable:   !slide.fixed,
      onClick:     () => selectSlide(slide.id),
      onDelete:    slide.fixed ? null : () => deleteSlide(slide.id),
      onDuplicate: slide.fixed ? null : () => duplicateSlide(slide.id),
      onAlias:     ALIAS_SOURCE_TYPES.includes(slide.type) ? () => createAlias(slide.id) : null,
      macroBadges,
      stageBadges: (isAlias ? '<span class="si-badge si-tag si-tag-alias" title="Repeats another slide and triggers its prop">Alias</span>' : '')
                 + stageDisplayBadgesHTML(effType, ...(hasBB ? [] : [posKey]))
                 + (slide.type === 'blank' ? qrBadgeHTML(effectiveQR(slide)) : ''),
      transBadge,
      propTransBadge,
    });

    if (!slide.fixed) {
      item.addEventListener('dragstart', onDragStart);
      item.addEventListener('dragend',   onDragEnd);
    }
    item.addEventListener('dragover',  onDragOver);
    item.addEventListener('dragleave', onDragLeave);
    item.addEventListener('drop',      onDrop);

    // Inject RC group just before END
    if (slide.type === 'end') {
      const RC_SUBITEMS = [
        { id: 'rcBlank',   label: 'RC Blank',      triggers: ['rcBlank'] },
        { id: 'rcContent', label: 'Response Card', triggers: ['rcContent', 'rcHold'] },
      ];
      const rcIsActive = state.activeId === 'rc';

      const rcGroup = document.createElement('div');
      rcGroup.className = 'rc-group';

      // Header row
      const rcHeader = makeSidebarItem({
        id:        'rc',
        cls:       rcIsActive ? 'active' : '',
        iconCls:   'si-rc',
        iconText:  'RC',
        label:     'Response Card',
        fixed:     true,
        draggable: false,
        onClick:   () => { state.activeId = 'rc'; render(); },
        macroBadges: [],
        stageBadges: '',
      });
      // Unfurl arrow button (toggle expand, stops click from opening RC panel)
      const ARROW_SVG = `<svg viewBox="0 0 8 8" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M2 3l2 2 2-2" stroke="currentColor" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round"/></svg>`;
      const arrowBtn = document.createElement('button');
      arrowBtn.className = `rc-unfurl-btn${rcGroupExpanded ? ' open' : ''}`;
      arrowBtn.title = rcGroupExpanded ? 'Collapse' : 'Expand';
      arrowBtn.innerHTML = ARROW_SVG;
      arrowBtn.addEventListener('click', e => {
        e.stopPropagation();
        rcGroupExpanded = !rcGroupExpanded;
        renderSidebar();
      });
      rcHeader.querySelector('.slide-icon')?.before(arrowBtn);
      rcGroup.appendChild(rcHeader);

      // Sub-items (only when expanded)
      if (rcGroupExpanded) {
        for (const sub of RC_SUBITEMS) {
          const subItem = makeSidebarItem({
            id:        sub.id,
            cls:       'rc-subitem',
            iconCls:   'si-rc',
            iconText:  'RC',
            label:     sub.label,
            fixed:     true,
            draggable: false,
            onClick:   () => { state.activeId = 'rc'; render(); },
            macroBadges: getSlideMacroBadges(...sub.triggers),
            stageBadges: stageDisplayBadgesHTML(...sub.triggers),
          });
          rcGroup.appendChild(subItem);
        }
      }

      queue.appendChild(rcGroup);
    }

    // Building (revealing) points unfurl like Response Card — one subitem
    // per bullet, since each bullet is its own output cue on export.
    if (slide.type === 'point' && slide.mode === 'revealing') {
      const isExpanded = expandedRevealGroups.has(slide.id);
      const group = document.createElement('div');
      group.className = 'rc-group';

      const ARROW_SVG = `<svg viewBox="0 0 8 8" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M2 3l2 2 2-2" stroke="currentColor" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round"/></svg>`;
      const arrowBtn = document.createElement('button');
      arrowBtn.className = `rc-unfurl-btn${isExpanded ? ' open' : ''}`;
      arrowBtn.title = isExpanded ? 'Collapse' : 'Expand';
      arrowBtn.innerHTML = ARROW_SVG;
      arrowBtn.addEventListener('click', e => {
        e.stopPropagation();
        if (isExpanded) expandedRevealGroups.delete(slide.id);
        else expandedRevealGroups.add(slide.id);
        renderSidebar();
      });
      item.querySelector('.slide-icon')?.before(arrowBtn);
      group.appendChild(item);

      if (isExpanded) {
        (slide.bullets || []).forEach((bullet, i) => {
          const text = bulletToText(bullet)?.trim() || `Bullet ${i + 1}`;
          const subItem = makeSidebarItem({
            id:          `${slide.id}-b${i}`,
            cls:         'rc-subitem',
            iconCls:     ic.cls,
            iconText:    String(i + 1),
            label:       text,
            fixed:       true,
            draggable:   false,
            onClick:     () => selectSlide(slide.id),
            macroBadges: [],
            stageBadges: '',
          });
          group.appendChild(subItem);
        });
      }

      queue.appendChild(group);
      continue;
    }

    queue.appendChild(item);
  }
}

// ─── Drag-to-reorder ──────────────────────────────────────────────────────────

let dragId = null;

function onDragStart(e) {
  const el = e.currentTarget; // null by the time the timeout runs
  dragId = el.dataset.id;
  e.dataTransfer.effectAllowed = 'move';
  setTimeout(() => { el.style.opacity = '0.4'; }, 0);
}

function onDragEnd(e) {
  e.currentTarget.style.opacity = '';
  document.querySelectorAll('.slide-item.drag-before, .slide-item.drag-after')
    .forEach(el => { el.classList.remove('drag-before'); el.classList.remove('drag-after'); });
  dragId = null;
}

function onDragOver(e) {
  e.preventDefault();
  e.dataTransfer.dropEffect = 'move';
  const el = e.currentTarget;
  if (el.dataset.id === dragId) return;
  const rect = el.getBoundingClientRect();
  const isBefore = e.clientY < rect.top + rect.height / 2;
  el.classList.toggle('drag-before', isBefore);
  el.classList.toggle('drag-after', !isBefore);
}

function onDragLeave(e) {
  e.currentTarget.classList.remove('drag-before');
  e.currentTarget.classList.remove('drag-after');
}

function onDrop(e) {
  e.preventDefault();
  const el = e.currentTarget;
  const targetId = el.dataset.id;
  const insertBefore = el.classList.contains('drag-before');
  el.classList.remove('drag-before');
  el.classList.remove('drag-after');
  if (!dragId || dragId === targetId) return;

  const fromIdx = state.slides.findIndex(s => s.id === dragId);
  const target  = state.slides.find(s => s.id === targetId);
  if (!target) return;

  const [moved] = state.slides.splice(fromIdx, 1);

  let toIdx = state.slides.findIndex(s => s.id === targetId);
  if (target.type === 'start') toIdx = 1;
  else if (target.type === 'end') toIdx = state.slides.length - 1;
  else if (!insertBefore) toIdx = toIdx + 1;
  toIdx = Math.max(1, Math.min(toIdx, state.slides.length - 1));

  state.slides.splice(toIdx, 0, moved);
  render();
}

// ─── Main panel ───────────────────────────────────────────────────────────────

// ── Slide editor preview ────────────────────────────────────────────────────
// The slide being edited, drawn with the active style exactly as export will:
// Fit Width's per-slide box and line breaks when it's on, else the style box.
const _spanText = b => Array.isArray(b) ? b.map(x => x.text || '').join('') : String(b || '');
function slidePreviewData(slide) {
  const pv = styleForExport(activeStyleScheme());
  const fit = !!slide.fitWidth, propFit = fit && !!slide.propFitWidth;
  const orDash = t => (t && String(t).trim()) ? t : '—';
  if (slide.type === 'scripture') {
    const body = (slide.bodies || [slide.body || []])[0] || [];
    // renderTextPreview draws `bold` spans in the emphasis (Bold row) style —
    // for scripture that's the ALT words (plain B is just \b on the body font).
    const pick = sp => (sp && sp.length ? sp : body).map(x => ({ text: x.text || '', bold: !!x.alt }));
    if (fit && slide.bodyW) { pv.bodyW = slide.bodyW; if (slide.bodyX != null) pv.bodyX = slide.bodyX; }
    if (propFit && slide.propBodyW) { pv.propBodyW = slide.propBodyW; if (slide.propBodyX != null) pv.propBodyX = slide.propBodyX; }
    const spans = pick(fit ? slide._fitBrokenSpans : null);
    return { pv, scene: 'scripture', content: {
      spans: spans.some(x => x.text.trim()) ? spans : [{ text: '—' }],
      propSpans: ((propFit && slide._fitPropBrokenSpans) || scriptureLedSpans(slide)).map(x => ({ text: x.text || '', bold: !!x.alt })),
      reference: orDash(slide.reference || slide.label) } };
  }
  if (slide.type === 'point') {
    if (fit && slide.bodyW) { pv.pointW = slide.bodyW; if (slide.bodyX != null) pv.pointX = slide.bodyX; }
    if (propFit && slide.propBodyW) { pv.propPointW = slide.propBodyW; if (slide.propBodyX != null) pv.propPointX = slide.propBodyX; }
    if (slide.mode === 'revealing') {
      const bullets = (slide.bullets || []).map(_spanText).filter(t => t.trim());
      return { pv, scene: 'stacked', content: { point: orDash(bullets[bullets.length - 1]), bullets: bullets.length ? bullets : ['—'] } };
    }
    const main = (fit && slide._fitBrokenText) || slide.bodyText;
    const led = slide.mode === 'split' ? ((propFit && slide._fitPropBrokenText) || slide.propBodyText || slide.bodyText)
                                       : ((propFit && slide._fitPropBrokenText) || slide.bodyText);
    return { pv, scene: 'point', content: { point: orDash(main), propPoint: orDash(led) } };
  }
  if (slide.type === 'start' || slide.type === 'end') {
    const dflt = slide.type === 'start' ? 'Start of Notes' : 'End of Notes';
    return { pv, scene: 'utility', content: { seText: slide.text ?? slide.label ?? dflt } };
  }
  return null;
}
let _slidePreviewOpen = (() => { try { return localStorage.getItem('deckpro.slidePreview') !== '0'; } catch (_) { return true; } })();
function slidePreviewHTML(slide) {
  const d = slidePreviewData(slide);
  if (!d) return '';
  const caption = slide.type === 'scripture' && (slide.bodies || []).length > 1 ? `Preview · first of ${(slide.bodies || []).length} slides` : 'Preview';
  return `<div class="slp-preview${_slidePreviewOpen ? '' : ' slp-closed'}">
    <button type="button" class="slp-toggle" aria-expanded="${_slidePreviewOpen}">${_slidePreviewOpen ? '▾' : '▸'} ${caption}
      <span class="slp-style">${esc(activeStyleScheme().name || '')}</span></button>
    ${_slidePreviewOpen ? `<div class="slp-body">${renderTextPreview(d.pv, d.scene, [], '', false, false, d.content)}</div>` : ''}
  </div>`;
}
// Insert the preview under the slide title and keep it in step with edits.
function mountSlidePreview(panel, slide) {
  const html = slidePreviewHTML(slide);
  if (!html) return;
  const h2 = panel.querySelector('.slide-form > h2');
  if (!h2) return;
  h2.insertAdjacentHTML('afterend', html);
  _tpLayout(panel.querySelector('.slp-preview'));
  if (panel._spWired) return;
  panel._spWired = true;
  let timer = 0;
  const refresh = () => {
    const host = panel.querySelector('.slp-preview');
    const cur = state.slides.find(x => x.id === state.activeId);
    if (!host || !cur) return;
    host.outerHTML = slidePreviewHTML(cur);
    _tpLayout(panel.querySelector('.slp-preview'));
  };
  const schedule = () => { clearTimeout(timer); timer = setTimeout(refresh, 150); };
  panel.addEventListener('input', e => { if (!e.target.closest('.slp-preview')) schedule(); });
  panel.addEventListener('change', e => { if (!e.target.closest('.slp-preview')) schedule(); });
  panel.addEventListener('click', e => {
    if (e.target.closest('.slp-toggle')) {
      _slidePreviewOpen = !_slidePreviewOpen;
      try { localStorage.setItem('deckpro.slidePreview', _slidePreviewOpen ? '1' : '0'); } catch (_) {}
      refresh();
      return;
    }
    if (panel.querySelector('.slp-preview')) schedule(); // Fit Width / mode buttons etc.
  });
}

function renderMain() {
  const panel = document.getElementById('main-panel');


  if (state.activeId === 'settings') { renderConfigPanel(panel);      return; }
  if (state.activeId === 'style')    { renderStylePanel(panel);        return; }
  if (state.activeId === 'rc')       { renderResponseCardPanel(panel); return; }

  const slide = state.slides.find(s => s.id === state.activeId);
  if (!slide) {
    panel.innerHTML = `
      <div class="panel-brand">
        <img src="assets/deckpro_wordmark_black.png" alt="DeckPro" class="panel-brand-logo">
        <div class="panel-brand-sub">v${APP_VERSION} &nbsp;·&nbsp; Lucca Grillo</div>
      </div>`;
    return;
  }

  if (slide.type === 'start' || slide.type === 'end') {
    panel.innerHTML = startEndForm(slide);
    mountSlidePreview(panel, slide);
    attachStartEndHandlers(slide);
    return;
  }

  switch (slide.type) {
    case 'blank':     panel.innerHTML = blankForm(slide);     break;
    case 'scripture': panel.innerHTML = scriptureForm(slide); break;
    case 'point':     panel.innerHTML = pointForm(slide);     break;
    case 'image':     panel.innerHTML = imageForm(slide);     break;
    case 'alias':     panel.innerHTML = aliasForm(slide);     break;
    case 'custom':    panel.innerHTML = customForm(slide);    break;
    case 'qrmarker':  panel.innerHTML = qrMarkerForm(slide);  return; // no form fields to wire
    default:          panel.innerHTML = '<div class="panel-empty">Unknown type</div>'; return;
  }
  mountSlidePreview(panel, slide);
  attachFormHandlers(slide);
}

// ─── Transition picker helper ─────────────────────────────────────────────────

function transitionRow(current, idPrefix) {
  const type = current?.type || 'default';
  const dur  = current?.duration ?? 0.6;
  const showDur = type !== 'default' && type !== 'cut';
  return `
    <div class="trans-row" id="${idPrefix}-trans-row">
      <div class="segmented-control trans-seg" id="${idPrefix}-trans-seg">
        <button data-val="default"  class="${type === 'default'  ? 'active' : ''}">Default</button>
        <button data-val="fade"     class="${type === 'fade'     ? 'active' : ''}">Fade</button>
        <button data-val="dissolve" class="${type === 'dissolve' ? 'active' : ''}">Dissolve</button>
        <button data-val="cut"      class="${type === 'cut'      ? 'active' : ''}">Cut</button>
      </div>
      <input type="number" class="trans-dur" id="${idPrefix}-trans-dur"
        value="${showDur ? dur : ''}" min="0.1" max="5" step="0.1" placeholder="s"
        style="display:${showDur ? 'block' : 'none'}">
    </div>
  `;
}

function attachTransitionHandlers(idPrefix, get, save) {
  const seg = document.getElementById(`${idPrefix}-trans-seg`);
  const dur = document.getElementById(`${idPrefix}-trans-dur`);
  if (!seg) return;
  seg.querySelectorAll('button').forEach(btn => {
    btn.addEventListener('click', () => {
      seg.querySelectorAll('button').forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      const val = btn.dataset.val;
      const showDur = val !== 'default' && val !== 'cut';
      dur.style.display = showDur ? 'block' : 'none';
      if (val === 'default') {
        save(null);
      } else if (val === 'cut') {
        save({ type: 'cut', duration: 0 });
      } else {
        save({ type: val, duration: parseFloat(dur.value) || 0.6 });
      }
    });
  });
  dur.addEventListener('input', () => {
    const active = seg.querySelector('button.active')?.dataset.val;
    if (active && active !== 'default' && active !== 'cut') {
      save({ type: active, duration: parseFloat(dur.value) || 0.6 });
    }
  });
}

// ─── Build order editor ───────────────────────────────────────────────────────

let _boActiveTab = 'content';

const BO_ELEMENTS = {
  content:  ['body', 'title', 'live'],
  point:    ['body', 'live'],
  blank:    ['body'],
  startEnd: ['body'],
};

const BO_STARTS = [
  ['START_WITH_SLIDE',    'After Transition'],
  ['ON_CLICK',            'On Click'],
  ['START_WITH_PREVIOUS', 'With Previous'],
  ['START_AFTER_PREVIOUS','After Previous'],
];

// Mirrors a real constraint in ProPresenter's own build-order UI: the FIRST
// build item in a slide's list can only start "After Transition" (i.e. as
// soon as the slide's own transition finishes — Pro7's actual term; "With
// Slide" isn't a real Pro7 option) or "On Click" — there's no earlier item
// for it to start "with"/"after". Every item AFTER the first can only
// reference the item directly above it — "On Click", "With Previous", or
// "After Previous" — "After Transition" only ever makes sense once, for
// whichever build the slide itself kicks off.
function validBoStartsForPosition(i) {
  return i === 0
    ? ['START_WITH_SLIDE', 'ON_CLICK']
    : ['ON_CLICK', 'START_WITH_PREVIOUS', 'START_AFTER_PREVIOUS'];
}
// Reordering/adding/removing rows can leave an entry's `start` invalid for its
// NEW position (e.g. deleting row 1 promotes row 2 — previously "With
// Previous" — into position 0, where that no longer means anything). Called
// after any structural change, once the caller already holds a forked
// (non-Global-inheriting) entries array, so it's always safe to mutate here.
function sanitizeBoStarts(entries) {
  entries.forEach((entry, i) => {
    if (!validBoStartsForPosition(i).includes(entry.start)) entry.start = 'ON_CLICK';
  });
}

const BO_TRANSITIONS = [
  ['cut',      'Cut'],
  ['dissolve', 'Dissolve'],
  ['fade',     'Fade'],
];

// ── Styles → Motion tab: same preview / list / inspector shape as Text ──────
// Transitions (main + LED) follow Global per field; builds follow Global as
// one set (scheme.buildOrders === null) until the first edit forks a copy.
const MOTION_ITEMS = () => [
  { id: 'slide',    group: 'Transitions', lbl: dn('mainScreen'), scene: 'scripture', kind: 'trans', typeF: 'transitionType',     durF: 'transitionDuration' },
  { id: 'prop',     group: 'Transitions', lbl: dn('ledWall'),    scene: 'scripture', kind: 'trans', typeF: 'propTransitionType', durF: 'propTransitionDuration' },
  { id: 'content',  group: 'Builds',      lbl: 'Scripture',      scene: 'scripture', kind: 'build' },
  { id: 'point',    group: 'Builds',      lbl: 'Point',          scene: 'point',     kind: 'build' },
  { id: 'startEnd', group: 'Builds',      lbl: 'Start / End',    scene: 'utility',   kind: 'build' },
];
// Build-order element name → [label, preview row] per slide type.
const BO_EL_INFO = {
  content:  { body: ['Verse text', 'body1'], title: ['Title', 'title1'], live: ['Live badge', 'live'] },
  point:    { body: ['Point text', 'point1'], live: ['Live badge', 'live'] },
  startEnd: { body: ['Text', 'se'] },
};
const TRANS_LABEL = { fade: 'Fade', dissolve: 'Dissolve', cut: 'Cut' };

function _boSentence(tab, e) {
  const el = BO_EL_INFO[tab]?.[e.element]?.[0] || e.element;
  const verb = e.dir === 'in' ? (e.transition === 'cut' ? 'appears' : 'fades in') : (e.transition === 'cut' ? 'disappears' : 'fades out');
  const when = { START_WITH_SLIDE: "the slide's transition finishes", ON_CLICK: 'the next click',
                 START_WITH_PREVIOUS: 'the step above starts', START_AFTER_PREVIOUS: 'the step above finishes' }[e.start] || '';
  const d = Number(e.delay) || 0;
  if (!d && e.start === 'ON_CLICK') return `${el} ${verb} on the next click.`;
  return `${el} ${verb} ${d ? `${d} s after` : 'when'} ${when}.`;
}

// Build steps as cards. Keeps the bo-* classes attachBuildRowHandlers binds.
function renderBuildTable(tab, scheme, locked) {
  const entries  = (scheme.buildOrders ?? ensureGlobalMotion().buildOrders)[tab] || [];
  const elements = BO_ELEMENTS[tab] || ['body'];
  const dis      = locked ? 'disabled' : '';
  const steps = entries.map((entry, i) => {
    const isCut = entry.transition === 'cut';
    return `
      <div class="mo-step${entry.enabled ? '' : ' mo-step-off'}">
        <div class="mo-step-hd">
          <span class="pt-layer-step mo-num">${i + 1}</span>
          <span class="mo-sentence">${esc(_boSentence(tab, entry))}</span>
          <label class="lt-switch mo-on"><input type="checkbox" class="bo-en" data-idx="${i}" ${entry.enabled ? 'checked' : ''} ${dis}> On</label>
          <span class="mo-step-btns">
            <button type="button" class="btn-sm bo-mv" data-dir="up"   data-idx="${i}" ${i === 0 || locked ? 'disabled' : ''} title="Move up">↑</button>
            <button type="button" class="btn-sm bo-mv" data-dir="down" data-idx="${i}" ${i === entries.length - 1 || locked ? 'disabled' : ''} title="Move down">↓</button>
            <button type="button" class="btn-sm bo-del" data-idx="${i}" ${dis} title="Remove step">×</button>
          </span>
        </div>
        <div class="tp-row">
          <div class="tp-num">Element<select class="tp-select bo-el" data-idx="${i}" ${dis}>
            ${elements.map(el => `<option value="${esc(el)}" ${entry.element === el ? 'selected' : ''}>${esc(BO_EL_INFO[tab]?.[el]?.[0] || el)}</option>`).join('')}
          </select></div>
          <div class="tp-num">Direction<select class="tp-select bo-dir" data-idx="${i}" ${dis}>
            <option value="in"  ${entry.dir === 'in'  ? 'selected' : ''}>In (show)</option>
            <option value="out" ${entry.dir === 'out' ? 'selected' : ''}>Out (hide)</option>
          </select></div>
          <div class="tp-num">Starts<select class="tp-select bo-start" data-idx="${i}" ${dis}>
            ${BO_STARTS.filter(([val]) => validBoStartsForPosition(i).includes(val))
              .map(([val, lbl]) => `<option value="${val}" ${entry.start === val ? 'selected' : ''}>${lbl}</option>`).join('')}
          </select></div>
          <div class="tp-num">Delay<span class="tp-cell"><input type="number" class="tp-input bo-num bo-delay" data-idx="${i}" value="${entry.delay ?? 0}" min="0" step="0.5" ${dis}><span class="tp-unit">s</span></span></div>
          <div class="tp-num">Animation<select class="tp-select bo-trans" data-idx="${i}" ${dis}>
            ${BO_TRANSITIONS.map(([val, lbl]) => `<option value="${val}" ${entry.transition === val ? 'selected' : ''}>${lbl}</option>`).join('')}
          </select></div>
          <div class="tp-num">Length<span class="tp-cell"><input type="number" class="tp-input bo-num bo-dur" data-idx="${i}" value="${isCut ? '' : (entry.duration ?? 0.6)}" min="0" max="10" step="0.1" ${isCut || locked ? 'disabled' : ''}><span class="tp-unit">s</span></span></div>
        </div>
      </div>`;
  }).join('');
  return `
    ${steps || '<p class="mo-empty">No builds — everything on the slide appears together with its transition.</p>'}
    <button type="button" class="btn-sm bo-add-btn" id="bo-add-btn" ${dis}>+ Add step</button>`;
}

function renderMotionTab(scheme, dis, locked, pv) {
  const items = MOTION_ITEMS();
  const cur = items.find(x => x.id === _motionSel) || items[0];
  _motionSel = cur.id;
  if (cur.kind === 'build') _boActiveTab = cur.id;
  const g = ensureGlobalMotion();
  const transOwn = it => scheme[it.typeF] != null || scheme[it.durF] != null;
  const buildsOwn = scheme.buildOrders != null;

  const list = ['Transitions', 'Builds'].map(grp => `
    <div class="tp-list-sec">${grp}</div>
    ${items.filter(x => x.group === grp).map(x => {
      const own = x.kind === 'trans' ? transOwn(x) : false;
      const sub = x.kind === 'trans'
        ? `${TRANS_LABEL[pv[x.typeF]] || 'Fade'}${pv[x.typeF] === 'cut' ? '' : ` ${pv[x.durF] ?? 0.6} s`}`
        : `${((pv.buildOrders || {})[x.id] || []).filter(e => e.enabled).length || 'no'} step${((pv.buildOrders || {})[x.id] || []).filter(e => e.enabled).length === 1 ? '' : 's'}`;
      return `<div role="button" tabindex="0" class="tp-list-item mo-item${x.id === cur.id ? ' active' : ''}" data-mo="${x.id}">
        <span>${esc(x.lbl)}<small class="mo-sub">${esc(sub)}</small></span>
        ${own ? '<span class="tp-dot" title="This style sets its own value"></span>' : ''}
      </div>`;
    }).join('')}`).join('');

  const status = (own, globalTxt, kind) => `<div class="pt-status">${own
    ? `<span class="pt-status-txt">Set for this style${globalTxt ? ` <span class="pt-muted">· Global is ${esc(globalTxt)}</span>` : ''}</span>
       <span class="pt-status-btns">
         <button type="button" class="btn-sm mo-use-global" data-kind="${kind}" ${dis}>↺ Use Global</button>
         <button type="button" class="btn-sm mo-make-global" data-kind="${kind}" ${dis}>↑ Make Global</button>
       </span>`
    : `<span class="pt-status-txt pt-muted">From Global — change it to set it for this style only</span>`}</div>`;

  let inspector;
  if (cur.kind === 'trans') {
    const type = pv[cur.typeF] || 'fade', dur = pv[cur.durF] ?? 0.6;
    const gTxt = `${TRANS_LABEL[g[cur.typeF]] || 'Fade'}${g[cur.typeF] === 'cut' ? '' : ` ${g[cur.durF]} s`}`;
    inspector = `
      <div class="tp-insp-hd">
        <div><span class="tp-insp-sec">Transition</span><span class="tp-insp-name">${esc(cur.lbl)}</span></div>
        <span class="tp-follow">${cur.id === 'slide' ? 'How each slide replaces the one before it.' : 'How each prop replaces the one before it on the LED wall.'}</span>
      </div>
      <div class="tp-group">
        <div class="tp-row">
          <div class="tp-num">Style<span class="tp-cell tp-seg">${['fade', 'dissolve', 'cut'].map(v =>
            `<button type="button" class="sg-align-cell tp-align mo-trans${type === v ? ' on' : ''}" data-kind="${cur.id}" data-val="${v}" ${dis}>${TRANS_LABEL[v]}</button>`).join('')}</span></div>
          ${type === 'cut' ? '' : `<div class="tp-num">Length<span class="tp-cell"><input type="number" class="tp-input mo-dur${scheme[cur.durF] == null ? ' lt-inherit' : ''}" data-kind="${cur.id}" value="${dur}" min="0.1" max="5" step="0.1" ${dis}><span class="tp-unit">s</span></span></div>`}
        </div>
        ${status(transOwn(cur), gTxt, cur.id)}
      </div>
      <p class="lt-note">Press ▶ Play on the preview to watch it. Empty the length to follow Global again.</p>`;
  } else {
    inspector = `
      <div class="tp-insp-hd">
        <div><span class="tp-insp-sec">Builds</span><span class="tp-insp-name">${esc(cur.lbl)}</span></div>
        <span class="tp-follow">Animate parts of the slide in or out after it appears.</span>
      </div>
      <div class="tp-group">
        ${status(buildsOwn, '', 'builds')}
        <p class="lt-note">Builds are kept as one set for Scripture, Point and Start / End — changing any of them gives this style its own copy of all three. Delays are real seconds (▶ Play shortens long ones).</p>
      </div>
      <div class="tp-group" id="bo-table-wrap">${renderBuildTable(cur.id, scheme, locked)}</div>`;
  }

  return `
    <div class="tp-preview mo-preview">
      ${renderTextPreview(pv, cur.scene, [], '', true, false)}
      <div class="mo-play-bar">
        <button type="button" class="btn-sm mo-play">▶ Play</button>
        <span class="mo-caption"></span>
      </div>
    </div>
    <div class="tp-body">
      <nav class="tp-list">${list}</nav>
      <div class="tp-insp">${inspector}</div>
    </div>`;
}

// Animate the selected transition, or the selected slide type's builds, on
// the preview. Long build delays are shortened so you don't wait a minute.
function playMotion(root, pv) {
  const host = root.querySelector('.mo-preview');
  const cur = MOTION_ITEMS().find(x => x.id === _motionSel);
  if (!host || !cur) return;
  const cap = host.querySelector('.mo-caption');
  const timers = [];
  const say = (t, ms) => timers.push(setTimeout(() => { cap.textContent = t; }, ms));
  const fadeIn = (els, ms, delay = 0) => els.forEach(e => e.animate([{ opacity: 0 }, { opacity: 1 }], { duration: Math.max(ms, 1), delay, fill: 'both', easing: 'ease-in-out' }));
  const fadeOut = (els, ms, delay = 0) => els.forEach(e => e.animate([{ opacity: 1 }, { opacity: 0 }], { duration: Math.max(ms, 1), delay, fill: 'both', easing: 'ease-in-out' }));
  host.getAnimations({ subtree: true }).forEach(a => a.cancel());

  const transOf = id => { const it = MOTION_ITEMS().find(x => x.id === id); return { type: pv[it.typeF] || 'fade', ms: (pv[it.typeF] === 'cut' ? 0 : (pv[it.durF] ?? 0.6)) * 1000 }; };
  const content = sel => [...host.querySelectorAll(`${sel} .tp-el, ${sel} .tp-gradient`)];
  let end;
  if (cur.kind === 'trans') {
    const canvas = cur.id === 'slide' ? '.tp-main' : '.tp-led';
    const { type, ms } = transOf(cur.id);
    const els = content(canvas);
    fadeOut(els, 1, 0);
    fadeIn(els, ms, 500);
    say(`${TRANS_LABEL[type]}${type === 'cut' ? '' : ` · ${ms / 1000} s`}`, 500);
    end = 500 + ms;
  } else {
    const { ms: tMs } = transOf('slide');
    const els = content('.tp-main');
    fadeOut(els, 1, 0);
    fadeIn(els, tMs, 400);
    say(`Slide transition · ${tMs / 1000} s`, 400);
    const entries = ((pv.buildOrders || {})[cur.id] || []).filter(e => e.enabled);
    const info = BO_EL_INFO[cur.id] || {};
    // Builds that bring something IN start hidden.
    for (const e of entries) {
      const row = info[e.element]?.[1];
      if (e.dir === 'in' && row) fadeOut([...host.querySelectorAll(`.tp-el[data-row="${row}"]`)], 1, 0);
    }
    let prevStart = 400 + tMs, prevEnd = 400 + tMs;
    entries.forEach((e, i) => {
      const realDelay = Number(e.delay) || 0;
      const delay = Math.min(realDelay, 1.5) * 1000;
      const len = e.transition === 'cut' ? 1 : (Number(e.duration) || 0.6) * 1000;
      const base = { START_WITH_SLIDE: 400 + tMs, ON_CLICK: prevEnd + 800, START_WITH_PREVIOUS: prevStart, START_AFTER_PREVIOUS: prevEnd }[e.start] ?? prevEnd;
      const at = base + delay;
      const row = info[e.element]?.[1];
      const targets = row ? [...host.querySelectorAll(`.tp-el[data-row="${row}"]`)] : [];
      (e.dir === 'in' ? fadeIn : fadeOut)(targets, len, at);
      const shortened = realDelay > 1.5 ? ` (really ${realDelay} s later — shortened)` : '';
      say(`Step ${i + 1}: ${_boSentence(cur.id, e).replace(/\.$/, '')}${e.start === 'ON_CLICK' ? ' — click' : ''}${shortened}`, base);
      prevStart = at; prevEnd = at + len;
    });
    if (!entries.length) say('No builds — everything appears with the slide', 400 + tMs);
    end = prevEnd;
  }
  timers.push(setTimeout(() => {
    host.getAnimations({ subtree: true }).forEach(a => a.cancel());
    cap.textContent = 'Done';
  }, end + 1600));
  root._moTimers?.forEach(clearTimeout);
  root._moTimers = timers;
}

// Navigation + Play for the Motion tab (works when locked — nothing here edits).
function wireMotionTab(root, getPv, rerender) {
  if (!root) return;
  _tpLayout(root);
  document.fonts?.ready.then(() => _tpLayout(root));
  root.addEventListener('click', e => {
    const item = e.target.closest('.mo-item');
    if (item) { _motionSel = item.dataset.mo; rerender(); return; }
    if (e.target.closest('.mo-play')) playMotion(root, getPv());
    // Add / move / delete step: the bo-* handler has already saved; redraw the
    // whole tab so the list counts and Global status catch up.
    if (e.target.closest('.bo-add-btn, .bo-mv, .bo-del')) setTimeout(rerender, 0);
  });
  // Step summaries and list counts follow edits (the bo-* handlers save first).
  root.addEventListener('change', e => { if (e.target.closest('#bo-table-wrap')) rerender(); });
  root.addEventListener('keydown', e => {
    if ((e.key === 'Enter' || e.key === ' ') && e.target.matches('.mo-item')) { e.preventDefault(); e.target.click(); }
  });
}

function attachBuildOrderHandlers(getScheme, panel, locked) {
  const wrap = panel.querySelector('#bo-table-wrap');
  if (!wrap) return;

  const getEntries = () => {
    const s = getScheme(); if (!s) return [];
    // Forking point: the first edit on an inheriting scheme materializes a copy
    // of Global's current build orders, then detaches from Global going forward.
    if (s.buildOrders == null) s.buildOrders = deepClone(ensureGlobalMotion().buildOrders);
    if (!Array.isArray(s.buildOrders[_boActiveTab])) s.buildOrders[_boActiveTab] = [];
    return s.buildOrders[_boActiveTab];
  };

  const refresh = () => {
    const s = getScheme(); if (!s) return;
    wrap.innerHTML = renderBuildTable(_boActiveTab, s, locked);
    attachBuildRowHandlers(getEntries, wrap, getScheme, panel, locked);
  };

  attachBuildRowHandlers(getEntries, wrap, getScheme, panel, locked);
}

function attachBuildRowHandlers(getEntries, wrap, getScheme, panel, locked) {
  if (locked) return;

  const refresh = () => {
    const s = getScheme(); if (!s) return;
    wrap.innerHTML = renderBuildTable(_boActiveTab, s, locked);
    attachBuildRowHandlers(getEntries, wrap, getScheme, panel, locked);
  };

  // ↑/↓ move
  wrap.querySelectorAll('.bo-mv').forEach(btn => {
    btn.addEventListener('click', () => {
      const entries = getEntries();
      const i = Number(btn.dataset.idx);
      if (btn.dataset.dir === 'up' && i > 0) {
        [entries[i - 1], entries[i]] = [entries[i], entries[i - 1]];
      } else if (btn.dataset.dir === 'down' && i < entries.length - 1) {
        [entries[i], entries[i + 1]] = [entries[i + 1], entries[i]];
      }
      sanitizeBoStarts(entries);
      saveState(); refresh();
    });
  });

  // Delete row
  wrap.querySelectorAll('.bo-del').forEach(btn => {
    btn.addEventListener('click', () => {
      const entries = getEntries();
      entries.splice(Number(btn.dataset.idx), 1);
      sanitizeBoStarts(entries);
      saveState(); refresh();
    });
  });

  // Enabled toggle
  wrap.querySelectorAll('.bo-en').forEach(inp => {
    inp.addEventListener('change', () => {
      getEntries()[Number(inp.dataset.idx)].enabled = inp.checked;
      saveState();
    });
  });

  // Element
  wrap.querySelectorAll('.bo-el').forEach(sel => {
    sel.addEventListener('change', () => {
      getEntries()[Number(sel.dataset.idx)].element = sel.value;
      saveState();
    });
  });

  // Direction
  wrap.querySelectorAll('.bo-dir').forEach(sel => {
    sel.addEventListener('change', () => {
      getEntries()[Number(sel.dataset.idx)].dir = sel.value;
      saveState();
    });
  });

  // Start type
  wrap.querySelectorAll('.bo-start').forEach(sel => {
    sel.addEventListener('change', () => {
      getEntries()[Number(sel.dataset.idx)].start = sel.value;
      saveState();
    });
  });

  // Delay
  wrap.querySelectorAll('.bo-delay').forEach(inp => {
    inp.addEventListener('input', () => {
      getEntries()[Number(inp.dataset.idx)].delay = parseFloat(inp.value) || 0;
      saveState();
    });
  });

  // Transition — show/hide Dur when Cut
  wrap.querySelectorAll('.bo-trans').forEach(sel => {
    sel.addEventListener('change', () => {
      const i = Number(sel.dataset.idx);
      getEntries()[i].transition = sel.value;
      const durInp = wrap.querySelector(`.bo-dur[data-idx="${i}"]`);
      if (durInp) {
        const isCut = sel.value === 'cut';
        durInp.disabled     = isCut;
        durInp.style.opacity = isCut ? '0.3' : '';
        if (isCut) durInp.value = '';
      }
      saveState();
    });
  });

  // Duration
  wrap.querySelectorAll('.bo-dur').forEach(inp => {
    inp.addEventListener('input', () => {
      getEntries()[Number(inp.dataset.idx)].duration = parseFloat(inp.value) || 0;
      saveState();
    });
  });

  // Add new row
  const addBtn = document.getElementById('bo-add-btn');
  if (addBtn) {
    addBtn.addEventListener('click', () => {
      const elements = BO_ELEMENTS[_boActiveTab] || ['this slide'];
      const entries = getEntries();
      entries.push({
        id: uid(), element: elements[0], dir: 'out',
        start: entries.length === 0 ? 'ON_CLICK' : 'START_AFTER_PREVIOUS', delay: 0,
        transition: 'dissolve', duration: 0.6, enabled: true,
      });
      saveState(); refresh();
    });
  }
}

// ─── Config / global settings panel ──────────────────────────────────────────

const CUSTOM_MACRO_TRIGGERS = [
  ['start',       'Start'],
  ['end',         'End'],
  ['scripture',   'Scripture'],
  ['point',       'Point'],
  ['blank',       'Blank'],
  ['blankBefore', 'Blank Before'],
  ['image',       'Image'],
  ['rcBlank',     'RC Blank'],
  ['rcContent',   'Response Card'],
];



function showMacroPicker(onSelect, singleSelect = false) {
  document.getElementById('macro-picker-overlay')?.remove();
  const liveMacros = pro7rt.liveMacros || [];
  const existing   = new Set((activeStyleScheme().macros ?? ensureGlobalMacros()).map(m => m.uuid));
  const selected   = new Set(); // UUIDs currently ticked

  const mName  = (m) => (m.id?.name?.string ?? m.id?.name ?? m.name?.string ?? m.name ?? '');
  const mUuid  = (m) => (m.id?.uuid?.string ?? m.id?.uuid ?? '');
  const mColor = (m) => {
    const c = m.color;
    if (!c) return null;
    return `rgba(${Math.round((c.red||0)*255)},${Math.round((c.green||0)*255)},${Math.round((c.blue||0)*255)},${c.alpha??1})`;
  };

  const overlay = document.createElement('div');
  overlay.className = 'macro-picker-overlay';
  overlay.id = 'macro-picker-overlay';
  overlay.innerHTML = `
    <div class="macro-picker-modal">
      <div class="macro-picker-header">
        <input type="text" class="macro-picker-search" placeholder="Search macros…" autocomplete="off" spellcheck="false">
        <button class="macro-picker-close" title="Cancel">×</button>
      </div>
      <div class="macro-picker-list"></div>
      <div class="macro-picker-footer">
        <span class="macro-picker-count">${liveMacros.length} macros from Pro7</span>
        <div style="display:flex;gap:6px;align-items:center">
          <button class="macro-picker-refresh">Refresh</button>
          <button class="macro-picker-add" disabled>Add 0</button>
        </div>
      </div>
    </div>
  `;
  document.body.appendChild(overlay);

  const search   = overlay.querySelector('.macro-picker-search');
  const list     = overlay.querySelector('.macro-picker-list');
  const closeBtn = overlay.querySelector('.macro-picker-close');
  const refresh  = overlay.querySelector('.macro-picker-refresh');
  const count    = overlay.querySelector('.macro-picker-count');
  const addBtn   = overlay.querySelector('.macro-picker-add');

  function updateAddBtn() {
    addBtn.disabled = selected.size === 0;
    addBtn.textContent = selected.size === 0 ? 'Add 0' : `Add ${selected.size}`;
  }

  function renderRows(filter = '') {
    const f = filter.trim().toLowerCase();
    if (!liveMacros.length) {
      list.innerHTML = `<div class="macro-picker-empty">No macros found — make sure Pro7 is connected.</div>`;
      return;
    }
    const filtered = liveMacros.filter(m => {
      const name = mName(m).toLowerCase();
      const uuid = mUuid(m).toLowerCase();
      return !f || name.includes(f) || uuid.includes(f);
    });
    if (!filtered.length) {
      list.innerHTML = `<div class="macro-picker-empty">No matches for "${esc(filter)}".</div>`;
      return;
    }
    list.innerHTML = filtered.map(m => {
      const name  = mName(m);
      const uuid  = mUuid(m);
      const color = mColor(m);
      const isExisting = existing.has(uuid);
      const isSel = selected.has(uuid);
      const dot = color ? `<span class="mpi-dot" style="background:${color}"></span>` : `<span class="mpi-dot mpi-dot-default"></span>`;
      return `<div class="macro-picker-row${isSel ? ' selected' : ''}${isExisting ? ' existing' : ''}" data-name="${esc(name)}" data-uuid="${esc(uuid)}" data-color="${esc(color||'')}">
        <span class="mpi-check">${isSel ? '✓' : ''}</span>
        ${dot}
        <span class="macro-picker-row-name">${esc(name)}</span>
        <code class="macro-picker-row-uuid">${esc(uuid)}</code>
        ${isExisting ? '<span class="mpi-existing">added</span>' : ''}
      </div>`;
    }).join('');
  }

  renderRows();
  setTimeout(() => search.focus(), 40);

  search.addEventListener('input', () => renderRows(search.value));
  attachPickerKeys(search, list);

  list.addEventListener('click', e => {
    const row = e.target.closest('.macro-picker-row');
    if (!row || row.classList.contains('existing')) return;
    const uuid = row.dataset.uuid;
    if (singleSelect) {
      // Immediately confirm selection
      const m = liveMacros.find(m2 => mUuid(m2) === uuid);
      overlay.remove();
      onSelect(m ? [{ name: mName(m), uuid, color: mColor(m) }] : []);
      return;
    }
    if (selected.has(uuid)) selected.delete(uuid); else selected.add(uuid);
    row.classList.toggle('selected', selected.has(uuid));
    row.querySelector('.mpi-check').textContent = selected.has(uuid) ? '\u2713' : '';
    updateAddBtn();
  });

  addBtn.addEventListener('click', () => {
    const result = [...selected].map(uuid => {
      const m = liveMacros.find(m => mUuid(m) === uuid);
      return m ? { name: mName(m), uuid, color: mColor(m) } : null;
    }).filter(Boolean);
    overlay.remove();
    onSelect(result);
  });

  refresh.addEventListener('click', async () => {
    refresh.textContent = 'Refreshing…';
    refresh.disabled = true;
    await fetchPro7Macros(true);
    liveMacros.length = 0;
    liveMacros.push(...(pro7rt.liveMacros || []));
    count.textContent = `${liveMacros.length} macros from Pro7`;
    refresh.textContent = 'Refresh';
    refresh.disabled = false;
    renderRows(search.value);
  });

  closeBtn.addEventListener('click', () => overlay.remove());
  overlay.addEventListener('click', e => { if (e.target === overlay) overlay.remove(); });
}

// attachMacrosPanelHandlers removed — macros are now per-scheme, managed in Schemes → Macros tab

function attachSchemesMacrosTab(containerId) {
  const el = document.getElementById(containerId);
  if (!el) return;

  const getScheme = () => state.styleSchemes.find(s => s.id === state.activeSchemeId) || state.styleSchemes[0];
  // Read-only: what to DISPLAY — falls to Global while the scheme is null (inheriting).
  const resolvedMacros = () => getScheme()?.macros ?? ensureGlobalMacros();
  // Fork point: first edit on an inheriting scheme materializes a copy of
  // Global's current macros, then detaches going forward.
  function fork() {
    const s = getScheme(); if (!s) return null;
    if (s.macros == null) s.macros = deepClone(ensureGlobalMacros());
    return s;
  }
  function badgeHtml() {
    const s = getScheme();
    const inherit = !s || s.macros == null;
    return `<div class="pt-status">${inherit
      ? '<span class="pt-status-txt pt-muted">From Global — change anything to set it for this style only</span>'
      : `<span class="pt-status-txt">Set for this style</span><span class="pt-status-btns">
          <button class="btn-sm" type="button" id="smac-wf-reset">↺ Use Global</button>
          <button class="btn-sm" type="button" id="smac-wf-push">↑ Make Global</button></span>`}</div>`;
  }

  function rerender() {
    const macros = resolvedMacros();
    el.querySelector('.smac-badge-wrap').innerHTML = badgeHtml();
    el.querySelector('.smac-list').innerHTML = macros.length ? macros.map((m, idx) => `
      <div class="smac-row custom-macro-row${(m.triggers || []).length || !m.uuid ? '' : ' smac-untriggered'}">
        <div class="custom-macro-fields">
          <span class="cm-dot" style="background:${macroDisplayColor(m)}"></span>
          <span class="cm-name-ro">${esc(m.name)}</span>
          <code class="cm-uuid-ro">${esc(m.uuid || '')}</code>
          <button class="btn-custom-del smac-del" data-idx="${idx}" title="Remove">×</button>
        </div>
        <div class="smac-chips">
          ${CUSTOM_MACRO_TRIGGERS.map(([key, label]) =>
            `<button class="cm-chip${(m.triggers || []).includes(key) ? ' active' : ''}" data-idx="${idx}" data-trigger="${key}">${label}</button>`
          ).join('')}
        </div>
        <div class="smac-pos-row">
          <span class="smac-pos-label">Slide #</span>
          ${(m.triggers || []).filter(t => /^pos:\d+$/.test(t)).map(t =>
            `<span class="smac-pos-chip" data-idx="${idx}" data-pos="${t}">#${t.slice(4)}<button class="smac-pos-rm" data-idx="${idx}" data-pos="${t}">×</button></span>`
          ).join('')}
          <input type="number" class="smac-pos-input" min="1" max="999" placeholder="add #" data-idx="${idx}">
        </div>
        ${((m.triggers || []).length || !m.uuid) ? '' : '<p class="smac-untriggered-note">No triggers — this won\'t fire on export. Pick a slide type or add a Slide #.</p>'}
      </div>`).join('')
    : `<p class="cm-empty">No macros for this scheme — click + Add Macro to import from Pro7.</p>`;
  }

  el.innerHTML = `
    <div class="smac-gradient-wrap"></div>
    <div class="smac-badge-wrap"></div>
    <div style="display:flex;justify-content:flex-end;margin-bottom:8px">
      <button class="btn-sm" id="smac-add-btn">+ Add Macro</button>
    </div>
    <div class="smac-list"></div>
  `;
  renderSingleMacroField(el.querySelector('.smac-gradient-wrap'), 'gradientMacro', 'Gradient',
    'Fires on Scripture, Point, and Response Card content cues — deck-wide, not per-style, since it\'s a real macro rather than visual style. See the QR Code tab for the version that fires instead when this export\'s QR toggle is on.');
  rerender();

  el.querySelector('#smac-add-btn').addEventListener('click', () => {
    showMacroPicker((selected) => {
      const scheme = fork();
      if (!scheme) return;
      for (const { name, uuid, color } of selected) {
        if (!scheme.macros.some(m => m.uuid === uuid))
          scheme.macros.push({ id: uid(), name, uuid, color, triggers: [] });
      }
      saveState();
      rerender();
    });
  });

  el.addEventListener('click', e => {
    if (e.target.id === 'smac-wf-reset') {
      const s = getScheme(); if (!s) return;
      s.macros = null;
      saveState(); rerender();
      return;
    }
    if (e.target.id === 'smac-wf-push') {
      state.globalMacros = deepClone(resolvedMacros());
      saveState(); rerender();
      toast('success', 'Pushed to Global', 'Every style inheriting macros will now use this.');
      return;
    }
    if (e.target.classList.contains('smac-del')) {
      const idx = parseInt(e.target.dataset.idx, 10);
      const scheme = fork();
      if (!isNaN(idx) && scheme?.macros) { scheme.macros.splice(idx, 1); saveState(); rerender(); }
    }
    if (e.target.classList.contains('cm-chip')) {
      const idx     = parseInt(e.target.dataset.idx, 10);
      const trigger = e.target.dataset.trigger;
      const scheme  = fork();
      if (isNaN(idx) || !scheme?.macros?.[idx]) return;
      const mTriggers = scheme.macros[idx].triggers || [];
      const ti = mTriggers.indexOf(trigger);
      if (ti === -1) mTriggers.push(trigger); else mTriggers.splice(ti, 1);
      scheme.macros[idx].triggers = mTriggers;
      saveState();
      rerender();
    }
    if (e.target.classList.contains('smac-pos-rm')) {
      const idx    = parseInt(e.target.dataset.idx, 10);
      const posKey = e.target.dataset.pos;
      const scheme = fork();
      if (isNaN(idx) || !scheme?.macros?.[idx]) return;
      const t = scheme.macros[idx].triggers || [];
      scheme.macros[idx].triggers = t.filter(x => x !== posKey);
      saveState(); rerender();
    }
  });

  el.addEventListener('keydown', e => {
    if (!e.target.classList.contains('smac-pos-input')) return;
    if (e.key !== 'Enter') return;
    const idx = parseInt(e.target.dataset.idx, 10);
    const n   = parseInt(e.target.value, 10);
    if (isNaN(idx) || isNaN(n) || n < 1) return;
    const posKey = `pos:${n}`;
    const scheme = fork();
    if (!scheme?.macros?.[idx]) return;
    const t = scheme.macros[idx].triggers || [];
    if (!t.includes(posKey)) { t.push(posKey); scheme.macros[idx].triggers = t; saveState(); }
    e.target.value = '';
    rerender();
  });
}

function attachSchemesStageTab(containerId) {
  const el = document.getElementById(containerId);
  if (!el) return;

  const getScheme = () => state.styleSchemes.find(s => s.id === state.activeSchemeId) || state.styleSchemes[0];
  // Read-only: what to DISPLAY — falls to Global while the scheme is null (inheriting).
  const resolvedStageDisplays = () => getScheme()?.stageDisplays ?? ensureGlobalStageDisplays();
  // Fork point: first edit on an inheriting scheme materializes a copy of
  // Global's current stage displays, then detaches going forward.
  function fork() {
    const s = getScheme(); if (!s) return null;
    if (s.stageDisplays == null) s.stageDisplays = deepClone(ensureGlobalStageDisplays());
    return s;
  }
  function badgeHtml() {
    const s = getScheme();
    const inherit = !s || s.stageDisplays == null;
    return `<div class="pt-status">${inherit
      ? '<span class="pt-status-txt pt-muted">From Global — change anything to set it for this style only</span>'
      : `<span class="pt-status-txt">Set for this style</span><span class="pt-status-btns">
          <button class="btn-sm" type="button" id="sstage-wf-reset">↺ Use Global</button>
          <button class="btn-sm" type="button" id="sstage-wf-push">↑ Make Global</button></span>`}</div>`;
  }

  const STAGE_ICON = `<svg style="width:10px;height:10px;vertical-align:middle;margin-right:3px" viewBox="0 0 10 10" fill="none" xmlns="http://www.w3.org/2000/svg"><rect x="2" y="1.3" width="6" height="4.2" rx="0.6" stroke="currentColor" stroke-width="1.1"/><path d="M5 5.5v1.6M3.3 7.9h3.4" stroke="currentColor" stroke-width="1.1" stroke-linecap="round"/></svg>`;

  // The physical Pro7 screen every stage layout targets. Per computer (each
  // Pro7 install makes its own screen UUIDs), so it lives in state.config and
  // is the same for every style.
  function screenRowHtml() {
    const ss    = state.config.stageScreen || DEFAULT_STAGESCREEN();
    const live  = pro7rt.liveStageScreens;
    const found = !live || !ss.screenUuid || live.some(sc => sc.uuid === ss.screenUuid);
    return `<div class="smac-row sstage-screen-row${found ? '' : ' sstage-screen-missing'}">
      <div class="custom-macro-fields">
        <span class="sstage-screen-label">Stage Screen</span>
        <span class="cm-name-ro">${esc(ss.screenName) || '<span style="color:var(--muted);font-style:italic;font-weight:400">none picked</span>'}</span>
        <code class="cm-uuid-ro">${esc(ss.screenUuid || '')}</code>
        <button class="btn-sm" type="button" id="sstage-screen-pick">Pick</button>
      </div>
      <p class="sstage-screen-note">${found
        ? 'The Pro7 output these layouts show on. Set once on each computer — every style uses it.'
        : 'This screen isn\'t in this computer\'s Pro7, so stage layouts won\'t change. Click Pick to choose the right one.'}</p>
    </div>`;
  }

  function rerender() {
    const entries = resolvedStageDisplays();
    el.querySelector('.sstage-screen-wrap').innerHTML = screenRowHtml();
    el.querySelector('.sstage-badge-wrap').innerHTML = badgeHtml();

    el.querySelector('.sstage-list').innerHTML = entries.length ? entries.map((d, idx) => `
      <div class="smac-row custom-macro-row${(d.triggers || []).length || !d.uuid ? '' : ' smac-untriggered'}">
        <div class="custom-macro-fields">
          <span class="cm-dot" style="background:var(--orange);opacity:.7">${STAGE_ICON}</span>
          <span class="cm-name-ro">${esc(d.name) || '<span style="color:var(--muted);font-style:italic;font-weight:400">no layout picked</span>'}</span>
          <code class="cm-uuid-ro">${esc(d.uuid || '')}</code>
          <button class="btn-sm sstage-pick" data-idx="${idx}">Pick</button>
          <button class="btn-custom-del sstage-del" data-idx="${idx}" title="Remove">×</button>
        </div>
        <div class="smac-chips">
          ${CUSTOM_MACRO_TRIGGERS.map(([key, label]) =>
            `<button class="cm-chip${(d.triggers || []).includes(key) ? ' active' : ''}" data-idx="${idx}" data-trigger="${key}">${label}</button>`
          ).join('')}
        </div>
        <div class="smac-pos-row">
          <span class="smac-pos-label">Slide #</span>
          ${(d.triggers || []).filter(t => /^pos:\d+$/.test(t)).map(t =>
            `<span class="smac-pos-chip" data-idx="${idx}" data-pos="${t}">#${t.slice(4)}<button class="smac-pos-rm sstage-pos-rm" data-idx="${idx}" data-pos="${t}">×</button></span>`
          ).join('')}
          <input type="number" class="smac-pos-input sstage-pos-input" min="1" max="999" placeholder="add #" data-idx="${idx}">
        </div>
        ${((d.triggers || []).length || !d.uuid) ? '' : '<p class="smac-untriggered-note">No triggers — this won\'t fire on export. Pick a slide type or add a Slide #.</p>'}
      </div>`).join('')
    : `<p class="cm-empty">No stage displays — click + Add Stage Display to pick a layout from Pro7.</p>`;
  }

  el.innerHTML = `
    <div class="sstage-screen-wrap"></div>
    <div class="sstage-badge-wrap"></div>
    <div style="display:flex;justify-content:flex-end;margin-bottom:8px">
      <button class="btn-sm" id="sstage-add-btn">+ Add Stage Display</button>
    </div>
    <div class="sstage-list smac-list"></div>
  `;
  rerender();
  if (pro7rt.connected && !pro7rt.liveStageScreens)
    fetchPro7StageScreens().then(() => { if (el.isConnected) rerender(); });

  // Add Stage Display button → multi-select picker
  el.querySelector('#sstage-add-btn').addEventListener('click', () => {
    showStageLayoutPicker(null, el.querySelector('#sstage-add-btn'), (results) => {
      const scheme = fork();
      if (!scheme || !results.length) return;
      for (const { name, uuid } of results)
        scheme.stageDisplays.push({ id: uid(), name, uuid, triggers: [] });
      saveState(); rerender();
    }, false);
  });

  // Trigger chip toggle
  el.addEventListener('click', e => {
    if (e.target.id === 'sstage-screen-pick') {
      showStageLayoutPicker(null, e.target, (name, uuid) => {
        state.config.stageScreen = Object.assign(DEFAULT_STAGESCREEN(), state.config.stageScreen || {},
          { screenName: name, screenUuid: uuid });
        saveState(); rerender();
      }, true, { screens: true });
      return;
    }
    if (e.target.id === 'sstage-wf-reset') {
      const s = getScheme(); if (!s) return;
      s.stageDisplays = null;
      saveState(); rerender();
      return;
    }
    if (e.target.id === 'sstage-wf-push') {
      state.globalStageDisplays = deepClone(resolvedStageDisplays());
      saveState(); rerender();
      toast('success', 'Pushed to Global', 'Every style inheriting stage displays will now use this.');
      return;
    }
    if (e.target.classList.contains('cm-chip') && e.target.closest('.sstage-list')) {
      const idx     = parseInt(e.target.dataset.idx, 10);
      const trigger = e.target.dataset.trigger;
      const scheme  = fork();
      if (isNaN(idx) || !scheme?.stageDisplays?.[idx]) return;
      const t  = scheme.stageDisplays[idx].triggers || [];
      const ti = t.indexOf(trigger);
      if (ti === -1) t.push(trigger); else t.splice(ti, 1);
      scheme.stageDisplays[idx].triggers = t;
      saveState();
      rerender();
    }
    if (e.target.classList.contains('sstage-del')) {
      const idx = parseInt(e.target.dataset.idx, 10);
      const scheme = fork();
      if (!isNaN(idx) && scheme?.stageDisplays) { scheme.stageDisplays.splice(idx, 1); saveState(); rerender(); }
    }
    if (e.target.classList.contains('sstage-pick')) {
      const idx = parseInt(e.target.dataset.idx, 10);
      showStageLayoutPicker(null, e.target, (name, uuid) => {
        const scheme = fork();
        if (!isNaN(idx) && scheme?.stageDisplays?.[idx]) {
          scheme.stageDisplays[idx].name = name;
          scheme.stageDisplays[idx].uuid = uuid;
          saveState(); rerender();
        }
      });
    }
    if (e.target.classList.contains('sstage-pos-rm')) {
      const idx    = parseInt(e.target.dataset.idx, 10);
      const posKey = e.target.dataset.pos;
      const scheme = fork();
      if (isNaN(idx) || !scheme?.stageDisplays?.[idx]) return;
      scheme.stageDisplays[idx].triggers = (scheme.stageDisplays[idx].triggers || []).filter(x => x !== posKey);
      saveState(); rerender();
    }
  });

  // Slide # input → Enter to add pos trigger
  el.addEventListener('keydown', e => {
    if (!e.target.classList.contains('sstage-pos-input')) return;
    if (e.key !== 'Enter') return;
    const idx = parseInt(e.target.dataset.idx, 10);
    const n   = parseInt(e.target.value, 10);
    if (isNaN(idx) || isNaN(n) || n < 1) return;
    const posKey = `pos:${n}`;
    const scheme = fork();
    if (!scheme?.stageDisplays?.[idx]) return;
    const t = scheme.stageDisplays[idx].triggers || [];
    if (!t.includes(posKey)) { t.push(posKey); scheme.stageDisplays[idx].triggers = t; saveState(); }
    e.target.value = '';
    rerender();
  });
}

// Response Card element editor (display-2 / LED wall prop). Lists the base
// elements (title, R1–R4) plus custom ones, each fully editable:
// name (= Pro7 object name), text, position (X/Y/W/H) and style (font/size/
// color/align). Response 1–4 text is filled from the Response Card deck item.
// Response Card element helpers, shared by the style tab and the Global view.
const RC_FROM_DECK = ['r1', 'r2', 'r3', 'r4'];
const RC_ROLE_LABEL = { title: 'Title', r1: 'Response 1', r2: 'Response 2', r3: 'Response 3', r4: 'Response 4', custom: 'Custom' };
// What export falls back to for an empty font/size/colour (buildProp's
// makePropStyle): the LED wall's Title for the title element, Body otherwise.
function rcInherited(pv, elObj) {
  const t = elObj.role === 'title';
  return {
    font: t ? pv.propTitleFont : pv.propBodyFont,
    size: t ? pv.propTitleSize : pv.propBodySize,
    color: ((t ? pv.propTitleFontAdv : pv.propBodyFontAdv) || {}).color || '#ffffff',
    lbl: t ? `${dn('ledWall')} Title` : `${dn('ledWall')} Body`,
  };
}
const rcTextOf = elObj => RC_FROM_DECK.includes(elObj.role)
  ? ((state.config.responses || {})[elObj.role] || RC_ROLE_LABEL[elObj.role])
  : (elObj.text || elObj.name || '');
function rcPreviewHTML(pv, els, sel) {
  const cw = pv.propCanvasW || 3200, ch = pv.propCanvasH || 1280;
  const boxes = els.map((e, i) => {
    const inh = rcInherited(pv, e);
    const adv = { ...FONT_ADV_DEFAULTS(), color: e.color || inh.color, alignment: e.align === 'left' ? '' : (e.align || 'center'), verticalAlignment: 'middle' };
    return _tpEl(pv, cw, ch, { row: `rc${i}`, box: [e.x ?? 0, e.y ?? 0, e.w ?? 2600, e.h ?? 150], font: e.font || inh.font,
      size: e.size || inh.size, adv, spans: [{ text: rcTextOf(e) }], sel: i === sel });
  }).join('');
  return `<div class="tp-canvas-block">
    <div class="lp-canvas-lbl">${esc(dn('ledWall'))} · Response Card · ${Math.round(cw)}×${Math.round(ch)}</div>
    <div class="tp-canvas tp-led" data-cw="${cw}" style="aspect-ratio:${cw} / ${ch}">${boxes}</div>
  </div>`;
}

function attachSchemesResponseCardTab(containerId) {
  const el = document.getElementById(containerId);
  if (!el) return;
  const getScheme = () => state.styleSchemes.find(s => s.id === state.activeSchemeId) || state.styleSchemes[0];
  const FROM_DECK = RC_FROM_DECK, ROLE_LABEL = RC_ROLE_LABEL;
  const families = (typeof _fontFamilyMap === 'object' && _fontFamilyMap) ? Object.keys(_fontFamilyMap).sort((a, b) => a.localeCompare(b)) : [];

  // Read-only: what to DISPLAY. s.rcElements stays null (following Global)
  // until an actual edit forks it via fork().
  const resolvedElements = () => getScheme()?.rcElements ?? ensureGlobalRcElements();
  function fork() {
    const s = getScheme(); if (!s) return null;
    if (s.rcElements == null) s.rcElements = deepClone(ensureGlobalRcElements());
    return s;
  }
  const inherited = rcInherited, preview = rcPreviewHTML;

  function render() {
    const s = getScheme();
    const pv = styleForExport(s);
    const els = resolvedElements();
    if (_rcSel >= els.length) _rcSel = 0;
    const cur = els[_rcSel];
    const own = s?.rcElements != null;
    const inh = cur ? inherited(pv, cur) : null;
    const curFam = cur?.font ? (fontFamilyOf(cur.font) || parseFontPS(cur.font).family) : '';
    const famOpts = `<option value=""${!cur?.font ? ' selected' : ''}>Same as ${esc(inh?.lbl || '')}</option>` +
      families.map(f => `<option value="${esc(f)}"${f === curFam ? ' selected' : ''}>${esc(f)}</option>`).join('');
    const styles = (_fontFamilyMap && _fontFamilyMap[curFam]) || [];
    const styOpts = cur?.font
      ? (styles.map(({ style, postscript }) => `<option value="${esc(postscript)}"${postscript === cur.font ? ' selected' : ''}>${esc(style)}</option>`).join('') || `<option value="${esc(cur.font)}">${esc(parseFontPS(cur.font).style || 'Regular')}</option>`)
      : '<option value="">—</option>';
    const num = (fld, label) => `<div class="tp-num">${label}<span class="tp-cell"><input type="number" class="tp-input rc-num" data-fld="${fld}" value="${cur?.[fld] ?? 0}" step="1"><span class="tp-unit">px</span></span></div>`;

    el.innerHTML = `
      <div class="tp-preview rc-preview">${preview(pv, els, _rcSel)}
        <p class="lt-note">Drag a box to move it, or its corner to resize. Responses 1–4 show this week's text from the Response Card item.</p>
      </div>
      <div class="tp-body">
        <nav class="tp-list">
          <div class="tp-list-sec">Elements</div>
          ${els.map((e, i) => `<div role="button" tabindex="0" class="tp-list-item rc-item${i === _rcSel ? ' active' : ''}" data-idx="${i}"><span>${esc(e.name || ROLE_LABEL[e.role] || 'Element')}</span>${e.role === 'custom' ? '<span class="tp-tag">custom</span>' : ''}</div>`).join('')}
          <button type="button" class="btn-sm rc-add" style="margin-top:8px">+ Add element</button>
        </nav>
        <div class="tp-insp">
          ${cur ? `
          <div class="tp-insp-hd">
            <div><span class="tp-insp-sec">${esc(ROLE_LABEL[cur.role] || 'Element')}</span><span class="tp-insp-name">${esc(cur.name || '')}</span></div>
            ${cur.role === 'custom' ? '<button type="button" class="btn-sm rc-del">Remove</button>' : ''}
          </div>
          <div class="tp-group">
            <div class="pt-status">${own
              ? `<span class="pt-status-txt">Set for this style</span><span class="pt-status-btns"><button type="button" class="btn-sm rc-use-global">↺ Use Global</button><button type="button" class="btn-sm rc-make-global">↑ Make Global</button></span>`
              : '<span class="pt-status-txt pt-muted">From Global — change anything to set it for this style only</span>'}</div>
          </div>
          <div class="tp-group">
            <div class="tp-group-lbl">Content</div>
            <div class="tp-row">
              <div class="tp-num tp-grow">Object name in ProPresenter<input type="text" class="tp-input rc-txt" data-fld="name" value="${esc(cur.name || '')}" style="width:100%;text-align:left"></div>
            </div>
            <div class="tp-row">
              ${FROM_DECK.includes(cur.role)
                ? `<div class="tp-num tp-grow">Text<span class="tp-na">From the Response Card item: “${esc((state.config.responses || {})[cur.role] || 'empty this week')}”</span></div>`
                : `<div class="tp-num tp-grow">Text<input type="text" class="tp-input rc-txt" data-fld="text" value="${esc(cur.text || '')}" style="width:100%;text-align:left"></div>`}
            </div>
          </div>
          <div class="tp-group">
            <div class="tp-group-lbl">Text style <span class="tp-group-sub">blank = same as ${esc(inh.lbl)}</span></div>
            <div class="tp-row">
              <div class="tp-num tp-grow">Font<select class="tp-select rc-sel" data-fld="fontFamily">${famOpts}</select></div>
              <div class="tp-num">Weight<select class="tp-select rc-sel" data-fld="fontWeight" ${cur.font ? '' : 'disabled'}>${styOpts}</select></div>
            </div>
            <div class="tp-row">
              <div class="tp-num">Size<span class="tp-cell"><input type="number" class="tp-input rc-num${cur.size ? '' : ' lt-inherit'}" data-fld="size" value="${cur.size || ''}" placeholder="${inh.size}" step="1"><span class="tp-unit">pt</span></span></div>
              <div class="tp-num">Colour<span class="tp-cell"><input type="color" class="tp-color rc-color" value="${normalizeHexColor(cur.color || inh.color)}">${cur.color ? '<button type="button" class="btn-sm rc-color-clear" title="Use the inherited colour">↺</button>' : ''}</span></div>
              <div class="tp-num">Align<span class="tp-cell tp-seg">${['left', 'center', 'right'].map(a =>
                `<button type="button" class="sg-align-cell tp-align rc-align${(cur.align || 'center') === a ? ' on' : ''}" data-align="${a}">${a[0].toUpperCase() + a.slice(1)}</button>`).join('')}</span></div>
            </div>
          </div>
          <div class="tp-group">
            <div class="tp-group-lbl">Position &amp; size</div>
            <div class="tp-row">${num('x', 'X')}${num('y', 'Y')}${num('w', 'Width')}${num('h', 'Height')}</div>
            <div class="tp-row"><button type="button" class="btn-sm rc-center">Center horizontally</button></div>
          </div>` : '<p class="mo-empty">No elements.</p>'}
        </div>
      </div>`;
    _tpLayout(el);
  }

  // Edit helper: fork from Global, change the selected element, save, redraw.
  const edit = (fn, redraw = true) => {
    const s = fork(); const e = s?.rcElements?.[_rcSel]; if (!e) return;
    fn(e, s);
    saveState();
    if (redraw) render();
  };

  render();

  el.addEventListener('click', e => {
    const item = e.target.closest('.rc-item');
    if (item) { _rcSel = Number(item.dataset.idx); render(); return; }
    const box = e.target.closest('.tp-el');
    if (box && !el._dragged) { _rcSel = Number(box.dataset.row.slice(2)); render(); return; }
    if (e.target.closest('.rc-align')) { edit(x => { x.align = e.target.closest('.rc-align').dataset.align; }); return; }
    if (e.target.closest('.rc-color-clear')) { edit(x => { x.color = ''; }); return; }
    if (e.target.closest('.rc-center')) {
      edit(x => { x.x = Math.round(((styleForExport(getScheme()).propCanvasW || 3200) - (x.w ?? 0)) / 2); });
      return;
    }
    if (e.target.closest('.rc-del')) {
      const s = fork(); if (!s) return;
      s.rcElements.splice(_rcSel, 1); _rcSel = Math.max(0, _rcSel - 1);
      saveState(); render(); return;
    }
    if (e.target.closest('.rc-add')) {
      const s = fork(); if (!s) return;
      s.rcElements.push({ id: uid(), role: 'custom', name: `Custom ${s.rcElements.filter(x => x.role === 'custom').length + 1}`, text: '', x: 400, y: 1080, w: 2600, h: 150, font: '', size: 0, color: '', align: 'center' });
      _rcSel = s.rcElements.length - 1;
      saveState(); render(); return;
    }
    if (e.target.closest('.rc-use-global')) { const s = getScheme(); if (s) { s.rcElements = null; saveState(); render(); } return; }
    if (e.target.closest('.rc-make-global')) {
      if (!confirm('Make these Response Card elements the Global default?\n\nStyles that follow Global will use them too.')) return;
      state.globalRcElements = deepClone(resolvedElements());
      const s = getScheme(); if (s) s.rcElements = null;
      saveState(); render();
      toast('success', 'Made Global', 'Styles following Global now use these Response Card elements.');
    }
  });
  el.addEventListener('keydown', e => {
    if ((e.key === 'Enter' || e.key === ' ') && e.target.matches('.rc-item')) { e.preventDefault(); e.target.click(); }
  });
  // Typing: save in place (keeps focus), refresh only the preview.
  el.addEventListener('input', e => {
    const t = e.target;
    if (t.classList.contains('rc-txt')) {
      edit(x => { x[t.dataset.fld] = t.value; }, false);
    } else if (t.classList.contains('rc-num')) {
      const v = parseInt(t.value, 10);
      edit(x => { x[t.dataset.fld] = Number.isFinite(v) ? v : 0; }, false);
    } else if (t.classList.contains('rc-color')) {
      edit(x => { x.color = t.value; }, false);
    } else return;
    const host = el.querySelector('.rc-preview .tp-canvas-block');
    if (host) { host.outerHTML = preview(styleForExport(getScheme()), resolvedElements(), _rcSel); _tpLayout(el); }
  });
  el.addEventListener('change', e => {
    const t = e.target;
    if (t.classList.contains('rc-sel')) {
      edit(x => {
        if (t.dataset.fld === 'fontFamily') x.font = t.value ? defaultFontStyle(t.value) : '';
        else x.font = t.value;
      });
    } else if (t.classList.contains('rc-txt') || t.classList.contains('rc-num') || t.classList.contains('rc-color')) {
      render(); // list names / status line catch up
    }
  });

  // Drag the selected box to move it, or its corner to resize.
  el.addEventListener('pointerdown', e => {
    const box = e.target.closest('.rc-preview .tp-el.sel');
    if (!box || e.button !== 0) return;
    const canvas = box.closest('.tp-canvas');
    const rect = canvas.getBoundingClientRect();
    const cw = Number(canvas.dataset.cw), scale = rect.width / cw, ch = rect.height / scale;
    const er = box.getBoundingClientRect();
    const resize = e.clientX > er.right - 14 && e.clientY > er.bottom - 14;
    const cur = resolvedElements()[_rcSel];
    const start = { x: cur.x ?? 0, y: cur.y ?? 0, w: cur.w ?? 0, h: cur.h ?? 0 };
    const next = { ...start };
    el._dragged = false;
    box.setPointerCapture(e.pointerId);
    const move = ev => {
      const dx = (ev.clientX - e.clientX) / scale, dy = (ev.clientY - e.clientY) / scale;
      if (Math.abs(dx) + Math.abs(dy) > 2) el._dragged = true;
      if (resize) { next.w = Math.max(10, Math.round(start.w + dx)); next.h = Math.max(10, Math.round(start.h + dy)); }
      else {
        next.x = Math.round(start.x + dx); next.y = Math.round(start.y + dy);
        if (Math.abs(next.x + next.w / 2 - cw / 2) < 8 / scale) next.x = Math.round((cw - next.w) / 2);
      }
      box.style.left = `${(next.x / cw * 100).toFixed(3)}%`; box.style.top = `${(next.y / ch * 100).toFixed(3)}%`;
      box.style.width = `${(next.w / cw * 100).toFixed(3)}%`; box.style.height = `${(next.h / ch * 100).toFixed(3)}%`;
      for (const f of ['x', 'y', 'w', 'h']) { const i = el.querySelector(`.rc-num[data-fld="${f}"]`); if (i) i.value = next[f]; }
    };
    const up = () => {
      box.removeEventListener('pointermove', move); box.removeEventListener('pointerup', up); box.removeEventListener('pointercancel', up);
      if (el._dragged) edit(x => Object.assign(x, next));
      setTimeout(() => { el._dragged = false; }, 0);
    };
    box.addEventListener('pointermove', move); box.addEventListener('pointerup', up); box.addEventListener('pointercancel', up);
  });
}

// Renders one "single macro assignment" field (label + value + Pick/Change
// button) into `container`, bound to state.config[key]. Used for QR Macro,
// Gradient, and Gradient (QR code version) — all deck-wide, not per-scheme,
// since these are unique real-world macros, not visual style. Multiple
// fields can share one container; each is scoped by `key`.
function renderSingleMacroField(container, key, label, hint) {
  const wrap = document.createElement('div');
  wrap.className = 'field';
  wrap.innerHTML = `
    <label>${esc(label)}</label>
    ${hint ? `<p class="style-group-hint">${hint}</p>` : ''}
    <div class="qr-macro-row" style="display:flex;align-items:center;gap:8px">
      <div class="${key}-val" style="display:flex;align-items:center;gap:6px;flex:1"></div>
      <button class="btn-sm" data-pick="${key}" type="button">Pick Macro</button>
    </div>
  `;
  container.appendChild(wrap);

  function rerender() {
    const m = state.config[key] || null;
    const dot = m && m.color
      ? `<span class="cm-dot" style="background:${m.color}"></span>`
      : `<span class="cm-dot cm-dot-default"></span>`;
    wrap.querySelector(`.${key}-val`).innerHTML = m
      ? `${dot}<span class="override-macro-name">${esc(m.name)}</span><code class="cm-uuid-ro">${esc(m.uuid || '')}</code>
         <button class="btn-custom-del" data-clear="${key}" title="Remove">×</button>`
      : `<span class="cm-empty" style="margin:0">No macro selected.</span>`;
    wrap.querySelector(`[data-pick="${key}"]`).textContent = m ? 'Change' : 'Pick Macro';
  }
  rerender();

  wrap.querySelector(`[data-pick="${key}"]`).addEventListener('click', () => {
    showMacroPicker((selected) => {
      if (selected.length) {
        const { name, uuid, color } = selected[0];
        state.config[key] = { name, uuid, color };
        saveState();
        rerender();
      }
    }, true);
  });

  wrap.addEventListener('click', (e) => {
    if (e.target.dataset.clear === key) {
      state.config[key] = null;
      saveState();
      rerender();
    }
  });
}

// QR Code tab: two deck-wide macro assignments — the QR Code macro itself
// (fires on blank-before cues with QR on) and a matching Gradient macro used
// on content cues instead of the normal one, whenever this export's QR
// toggle is on (see the Gradient field on the Macros tab for the non-QR one).
function attachSchemesQRTab(containerId) {
  const el = document.getElementById(containerId);
  if (!el) return;
  el.innerHTML = '';
  renderSingleMacroField(el, 'qrMacro', 'QR Macro',
    'QR Code is a macro, not an image DeckPro draws. Pick which macro fires on any blank slide with QR turned on — see the QR toggle next to "Blank slide before this one" on scripture/point/image slides, the Questions marker in the deck sidebar, and this deck\'s own QR toggle (Decks → edit this deck).');
  renderSingleMacroField(el, 'gradientMacroQr', 'Gradient (QR code version)',
    'Fires on Scripture, Point, and Response Card content cues instead of the normal Gradient macro (Macros tab), whenever this export\'s QR toggle is on — for a background treatment that matches the QR-configured look.');

  // External Content: the Questions marker hands the wall to an outside source.
  const ext = document.createElement('div');
  ext.className = 'field';
  ext.innerHTML = `
    <label>External Content</label>
    <p class="style-group-hint">For when something outside ProPresenter (e.g. an NDI feed) takes over the wall during Questions. When on, and this export's QR is on, the Questions marker exports a blank (QR) and then the Questions slide firing the start macro below; the very next slide fires the end macro so ProPresenter takes the wall back.</p>
    <div class="rc-toggle-row" id="external-content-row">
      <div class="toggle ${state.config.externalContent === true ? 'on' : ''}" id="external-content-toggle"></div>
      <span>Hand off to external content at Questions</span>
    </div>
  `;
  el.appendChild(ext);
  ext.querySelector('#external-content-row').addEventListener('click', () => {
    state.config.externalContent = state.config.externalContent !== true;
    ext.querySelector('#external-content-toggle').classList.toggle('on', state.config.externalContent);
    saveState();
  });
  renderSingleMacroField(el, 'externalStartMacro', 'External Content: start (on Questions)',
    'Fires on the Questions slide, alongside the QR macro — e.g. clear the series title and scripture so the outside source can use the wall.');
  renderSingleMacroField(el, 'externalEndMacro', 'External Content: end (next slide)',
    'Fires on the slide right after Questions (the next item\'s blank-before, or the item itself if it has none) — e.g. clear the outside source so ProPresenter takes the wall back.');
}

